INSERT INTO NPC (npcID, name, biography, contribution, asset) VALUES
(21, 'Tok Penglipur Lara', 'Penglipur lara tua yang mengembara dari kampung ke kampung menyampaikan cerita asal usul nama negeri.', 'Menyimpan dan menurunkan cerita asal usul nama negeri supaya warisan lisan tidak hilang.', 'orang_tradisi_lama.png'),
(22, 'Sultan (ketua negeri bersultan)', 'Ketua negeri bergelar Sultan, payung kepada negeri dan rakyatnya.', 'Memelihara adat dan menjadi payung kepada negeri yang diketuainya.', 'sultan.png'),
(23, 'Raja Perlis', 'Ketua negeri Perlis yang bergelar Raja.', 'Mewakili institusi diraja Perlis, satu-satunya negeri yang diketuai oleh Raja.', 'raja.png'),
(24, 'Yang di-Pertuan Besar Negeri Sembilan', 'Ketua negeri Negeri Sembilan yang dipilih oleh Undang Yang Empat.', 'Mewakili institusi diraja Negeri Sembilan yang dipilih mengikut adat.', 'yang_dipertuan_besar.png'),
(25, 'Yang di-Pertua Negeri', 'Ketua negeri bagi Melaka, Pulau Pinang, Sabah dan Sarawak yang dilantik oleh Yang di-Pertuan Agong.', 'Memegang jawatan ketua negeri untuk satu penggal empat tahun.', 'yang_dipertuan_negeri.png'),
(26, 'Pengembara Warisan', 'Pengembara yang mencatat ibu negeri, bandar diraja dan lagu negeri di seluruh Malaysia.', 'Memperkenalkan lambang kebanggaan setiap negeri kepada generasi muda.', 'jejaka_melayu.png'),
(27, 'Nelayan Tua', 'Nelayan tua yang tinggal di pesisir pantai dan gemar bercerita tentang nama tempat.', 'Menyimpan cerita lisan tentang nama pulau dan pantai.', 'nelayan.png'),
(28, 'Pesawah Padi', 'Pesawah di utara Semenanjung yang ingin tahu asal nama negerinya.', 'Mewakili rakyat biasa yang menjaga cerita kampung.', 'pesawah_padi.png'),
(29, 'Pemburu', 'Penduduk pantai timur yang menemui catatan lama di rumah datuknya.', 'Mewakili rakyat yang menyimpan catatan lama keluarga.', 'pemburu.png'),
(30, 'Peniaga Rumah Kedai', 'Peniaga bandar yang sering ditanya pelanggan tentang nama tempat.', 'Mewakili rakyat bandar yang ingin tahu asal usul tempat tinggalnya.', 'peniaga_rumah_kedai.png'),
(32, 'Nenek Dahulu', 'Warga emas yang masih mengingati warkah dan cerita istana lama.', 'Menyimpan ingatan tentang adat dan cerita istana.', 'nenek_dahulu.png'),
(33, 'Orang Bajau', 'Penduduk Sabah yang membawa nota dari kampungnya.', 'Mewakili masyarakat Sabah yang menyimpan cerita dan lagu negerinya.', 'orang_bajau.png'),
(34, 'Pemuda Sarawak', 'Pemuda Sarawak yang bangga dengan nama negerinya.', 'Mewakili anak muda Sarawak yang ingin menjaga cerita asal usul negerinya.', 'sarawakian.png'),
(35, 'Pemuzik Ulung', 'Pemuzik yang menjaga lagu-lagu negeri dalam dewan muzik tradisional.', 'Memelihara lagu negeri sebagai lambang kebanggaan.', 'pemuzik_ulung.png'),
(38, 'Budak Gajet', 'Kanak-kanak zaman moden yang baharu belajar tentang negerinya.', 'Mewakili generasi muda yang akan mewarisi cerita negeri.', 'budak_gajet.png')
INSERT INTO Narrative (narrativeID, narrativeTitle, eraID, summary) VALUES
(201, 'Rahsia di Sebalik Nama', 2, 'Masuki peranan Tok Penglipur Lara yang mengembara dari utara hingga Borneo. Di setiap negeri, penduduk berebut mendengar ceritamu tentang asal nama, ketua negeri, ibu negeri, bandar diraja, lagu, jata dan bendera.'),
(202, 'Payung Negeri: Takhta dan Tanggungjawab', 2, 'Masuki peranan seorang Sultan yang menerima kunjungan ketua-ketua negeri. Di setiap negeri, ketua negeri menguji kau tentang gelaran, asal nama, ibu negeri, bandar diraja, lagu, jata dan bendera.'),
(203, 'Jejak Ibu Negeri dan Lagu Kebanggaan', 2, 'Masuki peranan Pengembara Warisan yang menjelajah seluruh tanah air dengan buku catatan. Di setiap negeri, kau mencatat ibu negeri, bandar diraja, lagu, ketua negeri, asal nama, jata dan bendera.');
INSERT INTO Scene (sceneID, sceneStoryline, sceneOrder, narrativeID, asset) VALUES
('e2_n1_s1', 'Pagi di tepi sawah. Angin sawah menghembus padi yang menguning. Kau, Tok Penglipur Lara, melangkah masuk ke Perlis sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 1, 201, 'negeri_perlis.png'),
('e2_n1_s2', 'Senja di tengah sawah padi. Hamparan sawah padi berkilau di bawah langit senja. Kau, Tok Penglipur Lara, melangkah masuk ke Kedah sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 2, 201, 'negeri_kedah.png'),
('e2_n1_s3', 'Senja di jeti. Bau garam dan angin laut singgah di jeti yang sibuk. Kau, Tok Penglipur Lara, melangkah masuk ke Pulau Pinang sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 3, 201, 'negeri_pulau_pinang.png'),
('e2_n1_s4', 'Petang di halaman rumah beraja. Cahaya petang menyuluh halaman yang bersih disapu. Kau, Tok Penglipur Lara, melangkah masuk ke Perak sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 4, 201, 'negeri_perak.png'),
('e2_n1_s5', 'Pagi di tepi sungai. Air sungai mengalir tenang dan burung berkicau di tebing. Kau, Tok Penglipur Lara, melangkah masuk ke Selangor sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 5, 201, 'negeri_selangor.png'),
('e2_n1_s6', 'Petang di halaman rumah bergonjong. Bumbung bergonjong rumah adat tegak di hujung halaman. Kau, Tok Penglipur Lara, melangkah masuk ke Negeri Sembilan sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 6, 201, 'negeri_sembilan.png'),
('e2_n1_s7', 'Pagi di tepi sungai Melaka. Bunyi sungai dan bayangan kubu lama menyambut pagi. Kau, Tok Penglipur Lara, melangkah masuk ke Melaka sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 7, 201, 'negeri_melaka.png'),
('e2_n1_s8', 'Petang di tepi sungai. Angin petang menyapu permukaan sungai yang berkilat. Kau, Tok Penglipur Lara, melangkah masuk ke Johor sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 8, 201, 'negeri_johor.png'),
('e2_n1_s9', 'Pagi di tepi sungai. Kabus nipis naik dari sungai dan hutan di seberang. Kau, Tok Penglipur Lara, melangkah masuk ke Pahang sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 9, 201, 'negeri_pahang.png'),
('e2_n1_s10', 'Senja di tepi pantai. Ombak berbuih memukul pantai dan layang-layang camar berputar. Kau, Tok Penglipur Lara, melangkah masuk ke Terengganu sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 10, 201, 'negeri_terengganu.png'),
('e2_n1_s11', 'Petang di halaman rumah ukiran. Ukiran kayu berkilat di rumah tua yang harum dengan bunga. Kau, Tok Penglipur Lara, melangkah masuk ke Kelantan sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 11, 201, 'negeri_kelantan.png'),
('e2_n1_s12', 'Senja di tebing sungai. Air sungai berwarna teh mengalir lambat di bawah tebing. Kau, Tok Penglipur Lara, melangkah masuk ke Sarawak sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 12, 201, 'negeri_sarawak.png'),
('e2_n1_s13', 'Tengah hari di tepi teluk. Angin teluk berhembus sambil gong kecil berdenting jauh. Kau, Tok Penglipur Lara, melangkah masuk ke Sabah sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 13, 201, 'negeri_sabah.png'),
('e2_n1_s14', 'Malam di ibu kota. Lampu bandar menyala dan bunyi trafik bersahut-sahutan. Kau, Tok Penglipur Lara, melangkah masuk ke Wilayah Persekutuan sambil menjinjing tikar mengkuang, dan penduduk berebut duduk untuk mendengar cerita.', 14, 201, 'wilayah_persekutuan.png'),
('e2_n2_s1', 'Petang di tepi sungai. Angin petang menyapu permukaan sungai yang berkilat. Kau, seorang Sultan, bertamu ke Johor. Ketua negeri menyambut dengan hormat, tetapi di matanya ada teka-teki untuk kau.', 1, 202, 'negeri_johor.png'),
('e2_n2_s2', 'Senja di tengah sawah padi. Hamparan sawah padi berkilau di bawah langit senja. Kau, seorang Sultan, bertamu ke Kedah. Ketua negeri menyambut dengan hormat, tetapi di matanya ada teka-teki untuk kau.', 2, 202, 'negeri_kedah.png'),
('e2_n2_s3', 'Petang di halaman rumah ukiran. Ukiran kayu berkilat di rumah tua yang harum dengan bunga. Kau, seorang Sultan, bertamu ke Kelantan. Ketua negeri menyambut dengan hormat, tetapi di matanya ada teka-teki untuk kau.', 3, 202, 'negeri_kelantan.png'),
('e2_n2_s4', 'Pagi di tepi sungai. Kabus nipis naik dari sungai dan hutan di seberang. Kau, seorang Sultan, bertamu ke Pahang. Ketua negeri menyambut dengan hormat, tetapi di matanya ada teka-teki untuk kau.', 4, 202, 'negeri_pahang.png'),
