INSERT INTO Quest (questID, sceneID, questName, instruction, questType, description, questContent) VALUES
(201, 'e2_n1_s1', 'Nyahkod Catatan Lama Perlis', 'Baca catatan lama yang hampir pudar dan teka negeri yang dimaksudkan. Siasat dengan teliti!', '5', 'Mengenal pasti Perlis melalui asal nama.', '{"clueText": "Catatan lama, tulisan sudah pudar: namanya dikaitkan dengan Perkataan Siam ''phrau loi'', iaitu kelapa hanyut.", "options": [{"text": "Negeri itu ialah Perlis.", "isCorrect": true}, {"text": "Negeri itu ialah Perak.", "isCorrect": false, "consequence": "Maklumat itu sebenarnya milik Perak! Penduduk Perlis mengerut dahi dan berasa nama negeri mereka disalah ertikan."}, {"text": "Negeri itu ialah Melaka.", "isCorrect": false, "consequence": "Kau menyebut maklumat Melaka untuk Perlis. Orang ramai mencatatnya laju-laju, dan kesilapan itu pun tersebar dari mulut ke mulut."}], "aftermath": "Catatan itu dihantar ke negeri yang salah. Maklumat Perlis hilang daripada simpanan.", "turns": [{"after": 2, "options": [{"text": "Daripada perkataan Siam ''phrau loi'' (kelapa hanyut), perkataan tempatan ''peroleh'' atau tokoh Tok Perlis", "isCorrect": true, "reaction": "Betul, Tok! Jawapan itu kena tepat pada Perlis. Penduduk bertepuk tangan."}, {"text": "Dikaitkan dengan kilatan ikan di dalam air atau warna bijih timah putih yang berkilat seperti perak", "isCorrect": false, "reaction": "Eh, itu cerita Perak, Tok! Perlis lain ceritanya. Orang ramai mengerut dahi."}, {"text": "Sempena pokok Melaka tempat Parameswara berehat, atau ''Malakat'' dalam rujukan Arab yang bermaksud pusat pedagang", "isCorrect": false, "reaction": "Aduh, tersilap sedikit! Itu maklumat Melaka, bukan Perlis. Cuba ingat semula."}], "clue": "Ingat kata kunci tentang Perlis: kelapa hanyut."}]}'),
(202, 'e2_n1_s2', 'Soalan Sergahan di Kedah', 'Seseorang menahan kau di jalan! Bantu menjawab soalan tentang asal nama bagi Kedah.', '3', 'Mengenal pasti asal nama bagi Kedah.', '{"prompt": "Tiba-tiba seorang cikgu yang menjinjit bakul buku menahan kau dan bertanya: apakah asal usul nama Kedah?", "options": [{"text": "Daripada ''Kheddah'' (perangkap gajah), ''Qadah'' dalam bahasa Arab (gelas berkaki) atau ''Kadaram'' dalam rujukan India", "isCorrect": true}, {"text": "Sempena Sungai Selangor, pokok mentagau di kuala sungai, atau sejenis serangga yang disebut selangur", "isCorrect": false, "consequence": "Kau menyebut maklumat Selangor untuk Kedah. Orang ramai mencatatnya laju-laju, dan kesilapan itu pun tersebar dari mulut ke mulut."}, {"text": "Daripada perkataan Arab ''Jauhar'' (batu permata bernilai), dan dikenali sebagai Ujung Tanah dalam Sulalatus Salatin", "isCorrect": false, "consequence": "Itu fakta Johor, bukan Kedah! Pelajar yang mendengarnya menulis jawapan salah dalam buku, dan cikgu terpaksa membetulkannya kemudian."}], "aftermath": "Orang ramai pulang dengan jawapan Kedah yang salah, dan cerita itu tersebar semula dengan silap.", "turns": [{"after": 2, "options": [{"text": "Daripada ''Kheddah'' (perangkap gajah), ''Qadah'' dalam bahasa Arab (gelas berkaki) atau ''Kadaram'' dalam rujukan India", "isCorrect": true, "reaction": "Hebat, Tok! Itulah dia tentang Kedah. Semua mengangguk setuju."}, {"text": "Sempena Sungai Selangor, pokok mentagau di kuala sungai, atau sejenis serangga yang disebut selangur", "isCorrect": false, "reaction": "Aduh, tersilap sedikit! Itu maklumat Selangor, bukan Kedah. Cuba ingat semula."}, {"text": "Daripada perkataan Arab ''Jauhar'' (batu permata bernilai), dan dikenali sebagai Ujung Tanah dalam Sulalatus Salatin", "isCorrect": false, "reaction": "Hmm, itu milik Johor, bukan Kedah. Ada yang tergelak kecil di belakang."}], "clue": "Ingat kata kunci tentang Kedah: perangkap gajah."}]}'),
(203, 'e2_n1_s3', 'Misi Lambang: Jata, Bendera dan Radio Pulau Pinang', 'Cari jata, bendera dan radio pada gambar untuk mengenal pasti fakta tentang Pulau Pinang. Mata tajam, ya!', '2', 'Mengenal pasti maklumat asal nama bagi Pulau Pinang daripada jata, bendera dan radio.', '{"bgImage": "../assets/gameAsset/background/negeri_pulau_pinang.png", "hotspots": [{"name": "Pada jata: asal nama, berkait dengan pokok pinang", "top": "24%", "left": "68%"}, {"name": "Di tiang bendera: ketua negeri bergelar Yang di-Pertua Negeri", "top": "20%", "left": "46%"}, {"name": "Di radio: lagu ''Untuk Negeri Kita''", "top": "74%", "left": "10%"}], "aftermath": "Bukti tentang Pulau Pinang terlepas pandang. Catatan tentang jata, bendera dan lagunya menjadi samar, dan penduduk kecewa.", "turns": [{"after": 2, "options": [{"text": "Sempena pokok pinang yang banyak tumbuh di pulau itu, yang dahulu dikenali sebagai Pulo Ka Satu atau Tanjong Penaga", "isCorrect": true, "reaction": "Ya, ya, itulah jawapannya, Tok! Pulau Pinang memang begitu. Ada yang bersorak kecil."}, {"text": "Penyatuan sembilan luak asal seperti Sungai Ujong, Jelebu, Rembau dan Johol; perkataan negeri berasal daripada ''nagari''", "isCorrect": false, "reaction": "Hmm, itu milik Negeri Sembilan, bukan Pulau Pinang. Ada yang tergelak kecil di belakang."}, {"text": "Diambil daripada nama pokok mahang, dan dikenali juga sebagai Inderapura dalam catatan lama", "isCorrect": false, "reaction": "Silap negeri, Tok! Itu tentang Pahang, bukan Pulau Pinang. Cuba sekali lagi!"}], "clue": "Ingat kata kunci tentang Pulau Pinang: pokok pinang."}]}'),
(204, 'e2_n1_s4', 'Padanan Pantas: Asal nama', 'Cepat, padankan setiap negeri dengan asal namanya yang betul sebelum kad bercampur aduk!', '4', 'Mengenal pasti asal nama bagi Perak dan negeri lain.', '{"pairs": [{"text": "Perak", "pair": 1}, {"text": "Kilatan ikan atau bijih timah putih yang berkilat seperti perak", "pair": 1}, {"text": "Melaka", "pair": 2}, {"text": "Pokok Melaka tempat Parameswara berehat", "pair": 2}, {"text": "Terengganu", "pair": 3}, {"text": "''Taring anu'' (taring binatang liar) atau ''terang ganu'' (pelangi)", "pair": 3}, {"text": "Sabah", "pair": 4}, {"text": "Sejenis pisang, iaitu pisang saba atau pisang jaba", "pair": 4}], "aftermath": "Kad Perak tersalah letak, dan negeri-negeri lain pun ikut berselerak.", "turns": [{"after": 2, "options": [{"text": "Dikaitkan dengan kilatan ikan di dalam air atau warna bijih timah putih yang berkilat seperti perak", "isCorrect": true, "reaction": "Tepat sekali, Tok! Itulah maklumat Perak yang patut diingat. Sorakan bergema di sekeliling!"}, {"text": "Sempena pokok Melaka tempat Parameswara berehat, atau ''Malakat'' dalam rujukan Arab yang bermaksud pusat pedagang", "isCorrect": false, "reaction": "Silap negeri, Tok! Itu tentang Melaka, bukan Perak. Cuba sekali lagi!"}, {"text": "Daripada sebutan ''taring anu'' (taring harimau atau binatang liar) atau ''terang ganu'' yang bermaksud pelangi", "isCorrect": false, "reaction": "Eh, itu cerita Terengganu, Tok! Perak lain ceritanya. Orang ramai mengerut dahi."}], "clue": "Ingat kata kunci tentang Perak: bijih timah putih."}]}'),
(205, 'e2_n1_s5', 'Nyahkod Catatan Lama Selangor', 'Baca catatan lama yang hampir pudar dan teka negeri yang dimaksudkan. Siasat dengan teliti!', '5', 'Mengenal pasti Selangor melalui asal nama.', '{"clueText": "Catatan lama, tulisan sudah pudar: namanya dikaitkan dengan Sungai negeri ini, pokok mentagau atau serangga selangur.", "options": [{"text": "Negeri itu ialah Selangor.", "isCorrect": true}, {"text": "Negeri itu ialah Johor.", "isCorrect": false, "consequence": "Maklumat Johor tersasar masuk ke Selangor! Sekarang semua orang keliru dan perlu bertanya semula."}, {"text": "Negeri itu ialah Kelantan.", "isCorrect": false, "consequence": "Aduh, itu bukan Selangor, itu Kelantan! Catatan kau pun terpaksa dipadam dan ditulis semula."}], "aftermath": "Catatan itu dihantar ke negeri yang salah. Maklumat Selangor hilang daripada simpanan.", "turns": [{"after": 2, "options": [{"text": "Sempena Sungai Selangor, pokok mentagau di kuala sungai, atau sejenis serangga yang disebut selangur", "isCorrect": true, "reaction": "Betul, Tok! Jawapan itu kena tepat pada Selangor. Penduduk bertepuk tangan."}, {"text": "Daripada perkataan Arab ''Jauhar'' (batu permata bernilai), dan dikenali sebagai Ujung Tanah dalam Sulalatus Salatin", "isCorrect": false, "reaction": "Eh, itu cerita Johor, Tok! Selangor lain ceritanya. Orang ramai mengerut dahi."}, {"text": "Sebutan ''kilatan'' (cahaya terang) atau nama pokok gelam hutan, dan disebut Ho-lan-tan dalam rujukan China", "isCorrect": false, "reaction": "Aduh, tersilap sedikit! Itu maklumat Kelantan, bukan Selangor. Cuba ingat semula."}], "clue": "Ingat kata kunci tentang Selangor: sungai dan serangga."}]}'),
(206, 'e2_n1_s6', 'Soalan Sergahan di Negeri Sembilan', 'Seseorang menahan kau di jalan! Bantu menjawab soalan tentang asal nama bagi Negeri Sembilan.', '3', 'Mengenal pasti asal nama bagi Negeri Sembilan.', '{"prompt": "Tiba-tiba seorang peniaga yang sibuk menimbang barang menahan kau dan bertanya: apakah asal usul nama Negeri Sembilan?", "options": [{"text": "Penyatuan sembilan luak asal seperti Sungai Ujong, Jelebu, Rembau dan Johol; perkataan negeri berasal daripada ''nagari''", "isCorrect": true}, {"text": "Diambil daripada nama pokok mahang, dan dikenali juga sebagai Inderapura dalam catatan lama", "isCorrect": false, "consequence": "Aduh, itu bukan Negeri Sembilan, itu Pahang! Catatan kau pun terpaksa dipadam dan ditulis semula."}, {"text": "Berasal daripada Sungai Sarawak, logam antimoni yang disebut cerava, atau dialog ''serah kepada awak''", "isCorrect": false, "consequence": "Maklumat itu sebenarnya milik Sarawak! Penduduk Negeri Sembilan mengerut dahi dan berasa nama negeri mereka disalah ertikan."}], "aftermath": "Orang ramai pulang dengan jawapan Negeri Sembilan yang salah, dan cerita itu tersebar semula dengan silap.", "turns": [{"after": 2, "options": [{"text": "Penyatuan sembilan luak asal seperti Sungai Ujong, Jelebu, Rembau dan Johol; perkataan negeri berasal daripada ''nagari''", "isCorrect": true, "reaction": "Hebat, Tok! Itulah dia tentang Negeri Sembilan. Semua mengangguk setuju."}, {"text": "Diambil daripada nama pokok mahang, dan dikenali juga sebagai Inderapura dalam catatan lama", "isCorrect": false, "reaction": "Aduh, tersilap sedikit! Itu maklumat Pahang, bukan Negeri Sembilan. Cuba ingat semula."}, {"text": "Berasal daripada Sungai Sarawak, logam antimoni yang disebut cerava, atau dialog ''serah kepada awak''", "isCorrect": false, "reaction": "Hmm, itu milik Sarawak, bukan Negeri Sembilan. Ada yang tergelak kecil di belakang."}], "clue": "Ingat kata kunci tentang Negeri Sembilan: sembilan luak."}]}'),
