(214, 'e2_n1_s14', 'Soalan Sergahan di Wilayah Persekutuan', 'Seseorang menahan kau di jalan! Bantu menjawab soalan tentang asal nama bagi Wilayah Persekutuan.', '3', 'Mengenal pasti asal nama bagi Wilayah Persekutuan.', '{"prompt": "Tiba-tiba seorang peniaga yang sibuk menimbang barang menahan kau dan bertanya: apakah asal usul nama Wilayah Persekutuan?", "options": [{"text": "Kuala Lumpur daripada muara sungai berlumpur akibat perlombongan bijih timah, Labuan daripada ''labuhan'', Putrajaya sempena Tunku Abdul Rahman Putra", "isCorrect": true}, {"text": "Sempena pokok pinang yang banyak tumbuh di pulau itu, yang dahulu dikenali sebagai Pulo Ka Satu atau Tanjong Penaga", "isCorrect": false, "consequence": "Kau menyebut maklumat Pulau Pinang untuk Wilayah Persekutuan. Orang ramai mencatatnya laju-laju, dan kesilapan itu pun tersebar dari mulut ke mulut."}, {"text": "Penyatuan sembilan luak asal seperti Sungai Ujong, Jelebu, Rembau dan Johol; perkataan negeri berasal daripada ''nagari''", "isCorrect": false, "consequence": "Itu fakta Negeri Sembilan, bukan Wilayah Persekutuan! Pelajar yang mendengarnya menulis jawapan salah dalam buku, dan cikgu terpaksa membetulkannya kemudian."}], "aftermath": "Orang ramai pulang dengan jawapan Wilayah Persekutuan yang salah, dan cerita itu tersebar semula dengan silap.", "turns": [{"after": 2, "options": [{"text": "Kuala Lumpur daripada muara sungai berlumpur akibat perlombongan bijih timah, Labuan daripada ''labuhan'', Putrajaya sempena Tunku Abdul Rahman Putra", "isCorrect": true, "reaction": "Hebat, Tok! Itulah dia tentang Wilayah Persekutuan. Semua mengangguk setuju."}, {"text": "Sempena pokok pinang yang banyak tumbuh di pulau itu, yang dahulu dikenali sebagai Pulo Ka Satu atau Tanjong Penaga", "isCorrect": false, "reaction": "Aduh, tersilap sedikit! Itu maklumat Pulau Pinang, bukan Wilayah Persekutuan. Cuba ingat semula."}, {"text": "Penyatuan sembilan luak asal seperti Sungai Ujong, Jelebu, Rembau dan Johol; perkataan negeri berasal daripada ''nagari''", "isCorrect": false, "reaction": "Hmm, itu milik Negeri Sembilan, bukan Wilayah Persekutuan. Ada yang tergelak kecil di belakang."}], "clue": "Ingat kata kunci tentang Wilayah Persekutuan: muara berlumpur."}]}'),
(215, 'e2_n2_s1', 'Soalan Sergahan di Johor', 'Seseorang menahan kau di jalan! Bantu menjawab soalan tentang gelaran ketua negeri bagi Johor.', '3', 'Mengenal pasti gelaran ketua negeri bagi Johor.', '{"prompt": "Tiba-tiba seorang pelancong yang tercungap-cungap membawa peta menahan kau dan bertanya: apakah gelaran ketua negeri bagi Johor?", "options": [{"text": "Sultan", "isCorrect": true}, {"text": "Yang di-Pertuan Agong", "isCorrect": false, "consequence": "Maklumat itu sebenarnya milik Wilayah Persekutuan! Penduduk Johor mengerut dahi dan berasa nama negeri mereka disalah ertikan."}, {"text": "Yang di-Pertua Negeri", "isCorrect": false, "consequence": "Kau menyebut maklumat Pulau Pinang untuk Johor. Orang ramai mencatatnya laju-laju, dan kesilapan itu pun tersebar dari mulut ke mulut."}], "aftermath": "Jawapan tentang Johor tersasar. Soalan yang sama ditanya semula dan semua orang keliru.", "turns": [{"after": 2, "options": [{"text": "Sultan.", "isCorrect": true, "reaction": "Hebat, Tuanku! Itulah dia tentang Johor. Semua mengangguk setuju."}, {"text": "Yang di-Pertuan Agong.", "isCorrect": false, "reaction": "Eh, itu cerita Wilayah Persekutuan, Tuanku! Johor lain ceritanya. Orang ramai mengerut dahi."}, {"text": "Yang di-Pertua Negeri.", "isCorrect": false, "reaction": "Aduh, tersilap sedikit! Itu maklumat Pulau Pinang, bukan Johor. Cuba ingat semula."}], "clue": "Cuba ingat gambar Johor: jata, bendera dan radio di situ menyimpan petunjuknya."}]}'),
(216, 'e2_n2_s2', 'Misi Lambang: Jata, Bendera dan Radio Kedah', 'Cari jata, bendera dan radio pada gambar untuk mengenal pasti fakta tentang Kedah. Mata tajam, ya!', '2', 'Mengenal pasti maklumat gelaran ketua negeri bagi Kedah daripada jata, bendera dan radio.', '{"bgImage": "../assets/gameAsset/background/negeri_kedah.png", "hotspots": [{"name": "Pada jata: ketua negeri bergelar Sultan", "top": "52%", "left": "77%"}, {"name": "Di tiang bendera: asal nama, berkait dengan perangkap gajah", "top": "24%", "left": "29%"}, {"name": "Di radio: lagu ''Allah Selamatkan Sultan Mahkota''", "top": "73%", "left": "19%"}], "aftermath": "Jata, bendera dan radio Kedah tidak dibaca dengan teliti. Maklumat negeri itu hilang daripada ingatan.", "turns": [{"after": 2, "options": [{"text": "Sultan.", "isCorrect": true, "reaction": "Ya, ya, itulah jawapannya, Tuanku! Kedah memang begitu. Ada yang bersorak kecil."}, {"text": "Yang di-Pertuan Agong.", "isCorrect": false, "reaction": "Aduh, tersilap sedikit! Itu maklumat Wilayah Persekutuan, bukan Kedah. Cuba ingat semula."}, {"text": "Yang di-Pertua Negeri.", "isCorrect": false, "reaction": "Hmm, itu milik Pulau Pinang, bukan Kedah. Ada yang tergelak kecil di belakang."}], "clue": "Cuba ingat gambar Kedah: jata, bendera dan radio di situ menyimpan petunjuknya."}]}'),
