(226, 'e2_n2_s12', 'Nyahkod Catatan Lama Sabah', 'Baca catatan lama yang hampir pudar dan teka negeri yang dimaksudkan. Siasat dengan teliti!', '5', 'Mengenal pasti Sabah melalui gelaran ketua negeri.', '{"clueText": "Catatan lama, tulisan sudah pudar: ketua negeri ini bergelar Yang di-Pertua Negeri, dan ibu negerinya Kota Kinabalu.", "options": [{"text": "Negeri itu ialah Sabah.", "isCorrect": true}, {"text": "Negeri itu ialah Kedah.", "isCorrect": false, "consequence": "Aduh, itu bukan Sabah, itu Kedah! Catatan kau pun terpaksa dipadam dan ditulis semula."}, {"text": "Negeri itu ialah Wilayah Persekutuan.", "isCorrect": false, "consequence": "Maklumat itu sebenarnya milik Wilayah Persekutuan! Penduduk Sabah mengerut dahi dan berasa nama negeri mereka disalah ertikan."}], "aftermath": "Catatan lama tentang Sabah disalah baca, dan sejarah negeri itu ditulis dengan silap.", "turns": [{"after": 2, "options": [{"text": "Yang di-Pertua Negeri.", "isCorrect": true, "reaction": "Betul, Tuanku! Jawapan itu kena tepat pada Sabah. Penduduk bertepuk tangan."}, {"text": "Sultan.", "isCorrect": false, "reaction": "Silap negeri, Tuanku! Itu tentang Kedah, bukan Sabah. Cuba sekali lagi!"}, {"text": "Yang di-Pertuan Agong.", "isCorrect": false, "reaction": "Eh, itu cerita Wilayah Persekutuan, Tuanku! Sabah lain ceritanya. Orang ramai mengerut dahi."}], "clue": "Cuba ingat gambar Sabah: jata, bendera dan radio di situ menyimpan petunjuknya."}]}'),
(227, 'e2_n2_s13', 'Soalan Sergahan di Sarawak', 'Seseorang menahan kau di jalan! Bantu menjawab soalan tentang gelaran ketua negeri bagi Sarawak.', '3', 'Mengenal pasti gelaran ketua negeri bagi Sarawak.', '{"prompt": "Tiba-tiba seorang nenek yang sedang menyapu halaman menahan kau dan bertanya: apakah gelaran ketua negeri bagi Sarawak?", "options": [{"text": "Yang di-Pertua Negeri", "isCorrect": true}, {"text": "Raja", "isCorrect": false, "consequence": "Maklumat itu sebenarnya milik Perlis! Penduduk Sarawak mengerut dahi dan berasa nama negeri mereka disalah ertikan."}, {"text": "Sultan", "isCorrect": false, "consequence": "Kau menyebut maklumat Perak untuk Sarawak. Orang ramai mencatatnya laju-laju, dan kesilapan itu pun tersebar dari mulut ke mulut."}], "aftermath": "Jawapan tentang Sarawak tersasar. Soalan yang sama ditanya semula dan semua orang keliru.", "turns": [{"after": 2, "options": [{"text": "Yang di-Pertua Negeri.", "isCorrect": true, "reaction": "Hebat, Tuanku! Itulah dia tentang Sarawak. Semua mengangguk setuju."}, {"text": "Raja.", "isCorrect": false, "reaction": "Eh, itu cerita Perlis, Tuanku! Sarawak lain ceritanya. Orang ramai mengerut dahi."}, {"text": "Sultan.", "isCorrect": false, "reaction": "Aduh, tersilap sedikit! Itu maklumat Perak, bukan Sarawak. Cuba ingat semula."}], "clue": "Cuba ingat gambar Sarawak: jata, bendera dan radio di situ menyimpan petunjuknya."}]}'),
