(238, 'e2_n3_s10', 'Nyahkod Catatan Lama Terengganu', 'Baca catatan lama yang hampir pudar dan teka negeri yang dimaksudkan. Siasat dengan teliti!', '5', 'Mengenal pasti Terengganu melalui ibu negeri dan bandar diraja.', '{"clueText": "Catatan lama, tulisan sudah pudar: ibu negerinya Kuala Terengganu.", "options": [{"text": "Negeri itu ialah Terengganu.", "isCorrect": true}, {"text": "Negeri itu ialah Sabah.", "isCorrect": false, "consequence": "Hmm, itu cerita Sabah. Penduduk Terengganu saling berpandangan dan ada yang tergelak kecil kerana tersilap negeri."}, {"text": "Negeri itu ialah Kedah.", "isCorrect": false, "consequence": "Maklumat Kedah tersasar masuk ke Terengganu! Sekarang semua orang keliru dan perlu bertanya semula."}], "aftermath": "Catatan lama tentang Terengganu disalah baca, dan sejarah negeri itu ditulis dengan silap.", "turns": [{"after": 2, "options": [{"text": "Kuala Terengganu.", "isCorrect": true, "reaction": "Tepat sekali, pengembara! Itulah maklumat Terengganu yang patut diingat. Sorakan bergema di sekeliling!"}, {"text": "Kota Kinabalu.", "isCorrect": false, "reaction": "Aduh, tersilap sedikit! Itu maklumat Sabah, bukan Terengganu. Cuba ingat semula."}, {"text": "Alor Setar.", "isCorrect": false, "reaction": "Hmm, itu milik Kedah, bukan Terengganu. Ada yang tergelak kecil di belakang."}], "clue": "Cuba ingat gambar Terengganu: jata, bendera dan radio di situ menyimpan petunjuknya."}]}'),
(239, 'e2_n3_s11', 'Soalan Sergahan di Kelantan', 'Seseorang menahan kau di jalan! Bantu menjawab soalan tentang ibu negeri dan bandar diraja bagi Kelantan.', '3', 'Mengenal pasti ibu negeri dan bandar diraja bagi Kelantan.', '{"prompt": "Tiba-tiba seorang pelajar dengan buku nota penuh contengan menahan kau dan bertanya: apakah ibu negeri Kelantan?", "options": [{"text": "Kota Bharu", "isCorrect": true}, {"text": "Georgetown", "isCorrect": false, "consequence": "Maklumat Pulau Pinang tersasar masuk ke Kelantan! Sekarang semua orang keliru dan perlu bertanya semula."}, {"text": "Seremban, bandar diraja Seri Menanti", "isCorrect": false, "consequence": "Aduh, itu bukan Kelantan, itu Negeri Sembilan! Catatan kau pun terpaksa dipadam dan ditulis semula."}], "aftermath": "Jawapan tentang Kelantan tersasar. Soalan yang sama ditanya semula dan semua orang keliru.", "turns": [{"after": 2, "options": [{"text": "Kota Bharu.", "isCorrect": true, "reaction": "Betul, pengembara! Jawapan itu kena tepat pada Kelantan. Penduduk bertepuk tangan."}, {"text": "Georgetown.", "isCorrect": false, "reaction": "Hmm, itu milik Pulau Pinang, bukan Kelantan. Ada yang tergelak kecil di belakang."}, {"text": "Seremban.", "isCorrect": false, "reaction": "Silap negeri, pengembara! Itu tentang Negeri Sembilan, bukan Kelantan. Cuba sekali lagi!"}], "clue": "Cuba ingat gambar Kelantan: jata, bendera dan radio di situ menyimpan petunjuknya."}]}'),
(240, 'e2_n3_s12', 'Misi Lambang: Jata, Bendera dan Radio Sabah', 'Cari jata, bendera dan radio pada gambar untuk mengenal pasti fakta tentang Sabah. Mata tajam, ya!', '2', 'Mengenal pasti maklumat ibu negeri dan bandar diraja bagi Sabah daripada jata, bendera dan radio.', '{"bgImage": "../assets/gameAsset/background/negeri_sabah.png", "hotspots": [{"name": "Pada jata: ketua negeri bergelar Yang di-Pertua Negeri", "top": "46%", "left": "73%"}, {"name": "Di tiang bendera: ibu negeri Kota Kinabalu", "top": "38%", "left": "46%"}, {"name": "Di radio: lagu ''Sabah Tanah Airku''", "top": "73%", "left": "28%"}], "aftermath": "Jata, bendera dan radio Sabah tidak dibaca dengan teliti. Maklumat negeri itu hilang daripada ingatan.", "turns": [{"after": 2, "options": [{"text": "Kota Kinabalu.", "isCorrect": true, "reaction": "Hebat, pengembara! Itulah dia tentang Sabah. Semua mengangguk setuju."}, {"text": "Alor Setar.", "isCorrect": false, "reaction": "Silap negeri, pengembara! Itu tentang Kedah, bukan Sabah. Cuba sekali lagi!"}, {"text": "Shah Alam.", "isCorrect": false, "reaction": "Eh, itu cerita Selangor, pengembara! Sabah lain ceritanya. Orang ramai mengerut dahi."}], "clue": "Cuba ingat gambar Sabah: jata, bendera dan radio di situ menyimpan petunjuknya."}]}'),
(241, 'e2_n3_s13', 'Padanan Pantas: Ibu negeri dan bandar diraja', 'Cepat, padankan setiap negeri dengan ibu negeri dan bandar dirajanya yang betul sebelum kad bercampur aduk!', '4', 'Mengenal pasti ibu negeri dan bandar diraja bagi Sarawak dan negeri lain.', '{"pairs": [{"text": "Sarawak", "pair": 1}, {"text": "Kuching", "pair": 1}, {"text": "Perlis", "pair": 2}, {"text": "Kangar, bandar diraja Arau", "pair": 2}, {"text": "Perak", "pair": 3}, {"text": "Ipoh, bandar diraja Kuala Kangsar", "pair": 3}, {"text": "Melaka", "pair": 4}, {"text": "Bandar Melaka", "pair": 4}], "aftermath": "Maklumat Sarawak bercampur dengan negeri lain. Kekeliruan itu terus diulang dari mulut ke mulut.", "turns": [{"after": 2, "options": [{"text": "Kuching.", "isCorrect": true, "reaction": "Ya, ya, itulah jawapannya, pengembara! Sarawak memang begitu. Ada yang bersorak kecil."}, {"text": "Kangar.", "isCorrect": false, "reaction": "Eh, itu cerita Perlis, pengembara! Sarawak lain ceritanya. Orang ramai mengerut dahi."}, {"text": "Ipoh.", "isCorrect": false, "reaction": "Aduh, tersilap sedikit! Itu maklumat Perak, bukan Sarawak. Cuba ingat semula."}], "clue": "Cuba ingat gambar Sarawak: jata, bendera dan radio di situ menyimpan petunjuknya."}]}'),
(242, 'e2_n3_s14', 'Nyahkod Catatan Lama Wilayah Persekutuan', 'Baca catatan lama yang hampir pudar dan teka negeri yang dimaksudkan. Siasat dengan teliti!', '5', 'Mengenal pasti Wilayah Persekutuan melalui lagu negeri.', '{"clueText": "Catatan lama, tulisan sudah pudar: lagu negeri ini ialah ''Maju dan Sejahtera''.", "options": [{"text": "Negeri itu ialah Wilayah Persekutuan.", "isCorrect": true}, {"text": "Negeri itu ialah Pulau Pinang.", "isCorrect": false, "consequence": "Kau menyebut maklumat Pulau Pinang untuk Wilayah Persekutuan. Orang ramai mencatatnya laju-laju, dan kesilapan itu pun tersebar dari mulut ke mulut."}, {"text": "Negeri itu ialah Negeri Sembilan.", "isCorrect": false, "consequence": "Itu fakta Negeri Sembilan, bukan Wilayah Persekutuan! Pelajar yang mendengarnya menulis jawapan salah dalam buku, dan cikgu terpaksa membetulkannya kemudian."}], "aftermath": "Catatan lama tentang Wilayah Persekutuan disalah baca, dan sejarah negeri itu ditulis dengan silap.", "turns": [{"after": 2, "options": [{"text": "Maju dan Sejahtera.", "isCorrect": true, "reaction": "Tepat sekali, pengembara! Itulah maklumat Wilayah Persekutuan yang patut diingat. Sorakan bergema di sekeliling!"}, {"text": "Untuk Negeri Kita.", "isCorrect": false, "reaction": "Aduh, tersilap sedikit! Itu maklumat Pulau Pinang, bukan Wilayah Persekutuan. Cuba ingat semula."}, {"text": "Berkatlah Yang di-Pertuan Besar.", "isCorrect": false, "reaction": "Hmm, itu milik Negeri Sembilan, bukan Wilayah Persekutuan. Ada yang tergelak kecil di belakang."}], "clue": "Cuba ingat gambar Wilayah Persekutuan: jata, bendera dan radio di situ menyimpan petunjuknya."}]}');
INSERT INTO LearningSupport (questID, sceneID, supportType, hint, explanation, feedback) VALUES
(NULL, 'e2_n1_s1', 'hint', 'Cerita nama Perlis berkait dengan kelapa hanyut. Perhatikan jata, bendera dan radio di gambar ini.', NULL, NULL),
(201, NULL, 'hint', 'Ingat kata kunci kelapa hanyut. Jata, bendera dan radio di gambar ini menyimpan petunjuknya.', 'Perlis: asal nama, Perkataan Siam ''phrau loi'', iaitu kelapa hanyut. Ketua negeri Raja. Ibu negeri Kangar, bandar diraja Arau.', 'Hebat! Perlis kini terukir kemas dalam ingatan kau.'),
(NULL, 'e2_n1_s2', 'hint', 'Telinga tajam, mata tajam! Nama Kedah ada kaitan dengan perangkap gajah.', NULL, NULL),
(202, NULL, 'hint', 'Sst! Kata kunci hari ini ialah perangkap gajah. Tengok jata, bendera dan radio dengan teliti.', 'Kedah: asal nama, Perkataan ''Kheddah'', iaitu perangkap gajah. Ketua negeri Sultan. Ibu negeri Alor Setar, bandar diraja Anak Bukit. Lagu ''Allah Selamatkan Sultan Mahkota''.', 'Betul sekali! Jawapan kau membuat penduduk Kedah tersenyum bangga.'),
(NULL, 'e2_n1_s3', 'hint', 'Cerita nama Pulau Pinang berkait dengan pokok pinang. Perhatikan jata, bendera dan radio di gambar ini.', NULL, NULL),
(203, NULL, 'hint', 'Petunjuk rahsia: pokok pinang. Jata, bendera dan radio di gambar ini tidak berbohong.', 'Pulau Pinang: asal nama, Pokok pinang yang banyak tumbuh di pulau itu. Ketua negeri Yang di-Pertua Negeri. Ibu negeri Georgetown. Lagu ''Untuk Negeri Kita''.', 'Bagus! Satu lagi negeri berjaya kau takluki dengan ilmu!'),
(NULL, 'e2_n1_s4', 'hint', 'Telinga tajam, mata tajam! Nama Perak ada kaitan dengan bijih timah putih.', NULL, NULL),
(204, NULL, 'hint', 'Ingat kata kunci bijih timah putih. Jata, bendera dan radio di gambar ini menyimpan petunjuknya.', 'Perak: asal nama, Kilatan ikan atau bijih timah putih yang berkilat seperti perak. Ketua negeri Sultan (Takhtanya berpindah secara bergilir mengikut sistem penggiliran yang unik). Ibu negeri Ipoh, bandar diraja Kuala Kangsar. Lagu ''Allah Lanjutkan Usia Sultan''.', 'Tepat! Maklumat Perak kini lengkap dalam catatan kau, dan semua orang bersorak!'),
(NULL, 'e2_n1_s5', 'hint', 'Cerita nama Selangor berkait dengan sungai dan serangga. Perhatikan jata, bendera dan radio di gambar ini.', NULL, NULL),
(205, NULL, 'hint', 'Sst! Kata kunci hari ini ialah sungai dan serangga. Tengok jata, bendera dan radio dengan teliti.', 'Selangor: asal nama, Sungai Selangor, pokok mentagau atau serangga selangur. Ketua negeri Sultan. Ibu negeri Shah Alam, bandar diraja Klang. Lagu ''Duli Yang Maha Mulia''.', 'Hebat! Selangor kini terukir kemas dalam ingatan kau.'),
(NULL, 'e2_n1_s6', 'hint', 'Telinga tajam, mata tajam! Nama Negeri Sembilan ada kaitan dengan sembilan luak.', NULL, NULL),
(206, NULL, 'hint', 'Petunjuk rahsia: sembilan luak. Jata, bendera dan radio di gambar ini tidak berbohong.', 'Negeri Sembilan: asal nama, Penyatuan sembilan luak asal, dan ''nagari'' bermaksud wilayah. Ketua negeri Yang di-Pertuan Besar (Beliau dipilih oleh Undang Yang Empat). Ibu negeri Seremban, bandar diraja Seri Menanti. Lagu ''Berkatlah Yang di-Pertuan Besar''.', 'Betul sekali! Jawapan kau membuat penduduk Negeri Sembilan tersenyum bangga.'),
(NULL, 'e2_n1_s7', 'hint', 'Cerita nama Melaka berkait dengan pokok Melaka. Perhatikan jata, bendera dan radio di gambar ini.', NULL, NULL),
(207, NULL, 'hint', 'Ingat kata kunci pokok Melaka. Jata, bendera dan radio di gambar ini menyimpan petunjuknya.', 'Melaka: asal nama, Pokok Melaka tempat Parameswara berehat. Ketua negeri Yang di-Pertua Negeri. Ibu negeri Bandar Melaka. Lagu ''Melaka Maju Jaya''.', 'Bagus! Satu lagi negeri berjaya kau takluki dengan ilmu!'),
(NULL, 'e2_n1_s8', 'hint', 'Telinga tajam, mata tajam! Nama Johor ada kaitan dengan batu permata.', NULL, NULL),
(208, NULL, 'hint', 'Sst! Kata kunci hari ini ialah batu permata. Tengok jata, bendera dan radio dengan teliti.', 'Johor: asal nama, Perkataan Arab ''Jauhar'', iaitu batu permata bernilai. Ketua negeri Sultan. Ibu negeri Johor Bahru, bandar diraja Bandar Maharani. Lagu ''Lagu Bangsa Johor''.', 'Tepat! Maklumat Johor kini lengkap dalam catatan kau, dan semua orang bersorak!'),
(NULL, 'e2_n1_s9', 'hint', 'Cerita nama Pahang berkait dengan pokok mahang. Perhatikan jata, bendera dan radio di gambar ini.', NULL, NULL),
(209, NULL, 'hint', 'Petunjuk rahsia: pokok mahang. Jata, bendera dan radio di gambar ini tidak berbohong.', 'Pahang: asal nama, Pokok mahang, juga dikenali sebagai Inderapura. Ketua negeri Sultan. Ibu negeri Kuantan, bandar diraja Pekan. Lagu ''Allah Selamatkan Sultan Kami''.', 'Hebat! Pahang kini terukir kemas dalam ingatan kau.'),
(NULL, 'e2_n1_s10', 'hint', 'Telinga tajam, mata tajam! Nama Terengganu ada kaitan dengan pelangi.', NULL, NULL),
(210, NULL, 'hint', 'Ingat kata kunci pelangi. Jata, bendera dan radio di gambar ini menyimpan petunjuknya.', 'Terengganu: asal nama, ''Taring anu'' (taring binatang liar) atau ''terang ganu'' (pelangi). Ketua negeri Sultan. Ibu negeri Kuala Terengganu. Lagu ''Selamat Sultan''.', 'Betul sekali! Jawapan kau membuat penduduk Terengganu tersenyum bangga.'),
(NULL, 'e2_n1_s11', 'hint', 'Cerita nama Kelantan berkait dengan Ho-lan-tan. Perhatikan jata, bendera dan radio di gambar ini.', NULL, NULL),
(211, NULL, 'hint', 'Sst! Kata kunci hari ini ialah Ho-lan-tan. Tengok jata, bendera dan radio dengan teliti.', 'Kelantan: asal nama, Kilatan cahaya terang atau pokok gelam hutan. Ketua negeri Sultan. Ibu negeri Kota Bharu. Lagu ''Selamat Sultan''.', 'Bagus! Satu lagi negeri berjaya kau takluki dengan ilmu!'),
(NULL, 'e2_n1_s12', 'hint', 'Telinga tajam, mata tajam! Nama Sarawak ada kaitan dengan antimoni.', NULL, NULL),
(212, NULL, 'hint', 'Petunjuk rahsia: antimoni. Jata, bendera dan radio di gambar ini tidak berbohong.', 'Sarawak: asal nama, Sungai Sarawak, logam antimoni (cerava) atau ''serah kepada awak''. Ketua negeri Yang di-Pertua Negeri. Ibu negeri Kuching. Lagu ''Ibu Pertiwiku''.', 'Tepat! Maklumat Sarawak kini lengkap dalam catatan kau, dan semua orang bersorak!'),
(NULL, 'e2_n1_s13', 'hint', 'Cerita nama Sabah berkait dengan pisang saba. Perhatikan jata, bendera dan radio di gambar ini.', NULL, NULL),
(213, NULL, 'hint', 'Ingat kata kunci pisang saba. Jata, bendera dan radio di gambar ini menyimpan petunjuknya.', 'Sabah: asal nama, Sejenis pisang, iaitu pisang saba atau pisang jaba. Ketua negeri Yang di-Pertua Negeri. Ibu negeri Kota Kinabalu. Lagu ''Sabah Tanah Airku''.', 'Hebat! Sabah kini terukir kemas dalam ingatan kau.'),
(NULL, 'e2_n1_s14', 'hint', 'Telinga tajam, mata tajam! Nama Wilayah Persekutuan ada kaitan dengan muara berlumpur.', NULL, NULL),
(214, NULL, 'hint', 'Sst! Kata kunci hari ini ialah muara berlumpur. Tengok jata, bendera dan radio dengan teliti.', 'Wilayah Persekutuan: asal nama, Muara berlumpur (KL), labuhan (Labuan), sempena Tunku (Putrajaya). Ketua negeri Yang di-Pertuan Agong. Lagu ''Maju dan Sejahtera''.', 'Betul sekali! Jawapan kau membuat penduduk Wilayah Persekutuan tersenyum bangga.'),
(NULL, 'e2_n2_s1', 'hint', 'Setiap negeri ada gelaran ketua negerinya. Perhatikan jata, bendera dan radio Johor, dan ingat batu permata.', NULL, NULL),
(215, NULL, 'hint', 'Ingat kata kunci batu permata. Jata, bendera dan radio di gambar ini menyimpan petunjuknya.', 'Johor: asal nama, Perkataan Arab ''Jauhar'', iaitu batu permata bernilai. Ketua negeri Sultan. Ibu negeri Johor Bahru, bandar diraja Bandar Maharani. Lagu ''Lagu Bangsa Johor''.', 'Betul sekali! Jawapan kau membuat penduduk Johor tersenyum bangga.'),
