(224, NULL, 'hint', 'Ingat kata kunci pokok Melaka. Jata, bendera dan radio di gambar ini menyimpan petunjuknya.', 'Melaka: asal nama, Pokok Melaka tempat Parameswara berehat. Ketua negeri Yang di-Pertua Negeri. Ibu negeri Bandar Melaka. Lagu ''Melaka Maju Jaya''.', 'Bagus! Satu lagi negeri berjaya kau takluki dengan ilmu!'),
(NULL, 'e2_n2_s11', 'hint', 'Setiap negeri ada gelaran ketua negerinya. Perhatikan jata, bendera dan radio Pulau Pinang, dan ingat pokok pinang.', NULL, NULL),
(225, NULL, 'hint', 'Sst! Kata kunci hari ini ialah pokok pinang. Tengok jata, bendera dan radio dengan teliti.', 'Pulau Pinang: asal nama, Pokok pinang yang banyak tumbuh di pulau itu. Ketua negeri Yang di-Pertua Negeri. Ibu negeri Georgetown. Lagu ''Untuk Negeri Kita''.', 'Tepat! Maklumat Pulau Pinang kini lengkap dalam catatan kau, dan semua orang bersorak!'),
(NULL, 'e2_n2_s12', 'hint', 'Gelaran ketua negeri Sabah tersimpan pada jata dan bendera. Kata kunci: pisang saba.', NULL, NULL),
(226, NULL, 'hint', 'Petunjuk rahsia: pisang saba. Jata, bendera dan radio di gambar ini tidak berbohong.', 'Sabah: asal nama, Sejenis pisang, iaitu pisang saba atau pisang jaba. Ketua negeri Yang di-Pertua Negeri. Ibu negeri Kota Kinabalu. Lagu ''Sabah Tanah Airku''.', 'Hebat! Sabah kini terukir kemas dalam ingatan kau.'),
(NULL, 'e2_n2_s13', 'hint', 'Setiap negeri ada gelaran ketua negerinya. Perhatikan jata, bendera dan radio Sarawak, dan ingat antimoni.', NULL, NULL),
(227, NULL, 'hint', 'Ingat kata kunci antimoni. Jata, bendera dan radio di gambar ini menyimpan petunjuknya.', 'Sarawak: asal nama, Sungai Sarawak, logam antimoni (cerava) atau ''serah kepada awak''. Ketua negeri Yang di-Pertua Negeri. Ibu negeri Kuching. Lagu ''Ibu Pertiwiku''.', 'Betul sekali! Jawapan kau membuat penduduk Sarawak tersenyum bangga.'),
(NULL, 'e2_n2_s14', 'hint', 'Gelaran ketua negeri Wilayah Persekutuan tersimpan pada jata dan bendera. Kata kunci: muara berlumpur.', NULL, NULL),
(228, NULL, 'hint', 'Sst! Kata kunci hari ini ialah muara berlumpur. Tengok jata, bendera dan radio dengan teliti.', 'Wilayah Persekutuan: asal nama, Muara berlumpur (KL), labuhan (Labuan), sempena Tunku (Putrajaya). Ketua negeri Yang di-Pertuan Agong. Lagu ''Maju dan Sejahtera''.', 'Bagus! Satu lagi negeri berjaya kau takluki dengan ilmu!'),
(NULL, 'e2_n3_s1', 'hint', 'Catat ibu negeri, bandar diraja dan lagu Perlis. Jata, bendera dan radio di gambar ini membantu kau ingat.', NULL, NULL),
(229, NULL, 'hint', 'Ingat kata kunci kelapa hanyut. Jata, bendera dan radio di gambar ini menyimpan petunjuknya.', 'Perlis: asal nama, Perkataan Siam ''phrau loi'', iaitu kelapa hanyut. Ketua negeri Raja. Ibu negeri Kangar, bandar diraja Arau.', 'Bagus! Satu lagi negeri berjaya kau takluki dengan ilmu!'),
(NULL, 'e2_n3_s2', 'hint', 'Buku catatan sedia? Ibu negeri, bandar diraja dan lagu Kedah ada di sekeliling kau.', NULL, NULL),
(230, NULL, 'hint', 'Sst! Kata kunci hari ini ialah perangkap gajah. Tengok jata, bendera dan radio dengan teliti.', 'Kedah: asal nama, Perkataan ''Kheddah'', iaitu perangkap gajah. Ketua negeri Sultan. Ibu negeri Alor Setar, bandar diraja Anak Bukit. Lagu ''Allah Selamatkan Sultan Mahkota''.', 'Tepat! Maklumat Kedah kini lengkap dalam catatan kau, dan semua orang bersorak!'),
(NULL, 'e2_n3_s3', 'hint', 'Catat ibu negeri, bandar diraja dan lagu Pulau Pinang. Jata, bendera dan radio di gambar ini membantu kau ingat.', NULL, NULL),
(231, NULL, 'hint', 'Petunjuk rahsia: pokok pinang. Jata, bendera dan radio di gambar ini tidak berbohong.', 'Pulau Pinang: asal nama, Pokok pinang yang banyak tumbuh di pulau itu. Ketua negeri Yang di-Pertua Negeri. Ibu negeri Georgetown. Lagu ''Untuk Negeri Kita''.', 'Hebat! Pulau Pinang kini terukir kemas dalam ingatan kau.'),
(NULL, 'e2_n3_s4', 'hint', 'Buku catatan sedia? Ibu negeri, bandar diraja dan lagu Perak ada di sekeliling kau.', NULL, NULL),
(232, NULL, 'hint', 'Ingat kata kunci bijih timah putih. Jata, bendera dan radio di gambar ini menyimpan petunjuknya.', 'Perak: asal nama, Kilatan ikan atau bijih timah putih yang berkilat seperti perak. Ketua negeri Sultan (Takhtanya berpindah secara bergilir mengikut sistem penggiliran yang unik). Ibu negeri Ipoh, bandar diraja Kuala Kangsar. Lagu ''Allah Lanjutkan Usia Sultan''.', 'Betul sekali! Jawapan kau membuat penduduk Perak tersenyum bangga.'),
(NULL, 'e2_n3_s5', 'hint', 'Catat ibu negeri, bandar diraja dan lagu Selangor. Jata, bendera dan radio di gambar ini membantu kau ingat.', NULL, NULL),
(233, NULL, 'hint', 'Sst! Kata kunci hari ini ialah sungai dan serangga. Tengok jata, bendera dan radio dengan teliti.', 'Selangor: asal nama, Sungai Selangor, pokok mentagau atau serangga selangur. Ketua negeri Sultan. Ibu negeri Shah Alam, bandar diraja Klang. Lagu ''Duli Yang Maha Mulia''.', 'Bagus! Satu lagi negeri berjaya kau takluki dengan ilmu!'),
(NULL, 'e2_n3_s6', 'hint', 'Buku catatan sedia? Ibu negeri, bandar diraja dan lagu Negeri Sembilan ada di sekeliling kau.', NULL, NULL),
(234, NULL, 'hint', 'Petunjuk rahsia: sembilan luak. Jata, bendera dan radio di gambar ini tidak berbohong.', 'Negeri Sembilan: asal nama, Penyatuan sembilan luak asal, dan ''nagari'' bermaksud wilayah. Ketua negeri Yang di-Pertuan Besar (Beliau dipilih oleh Undang Yang Empat). Ibu negeri Seremban, bandar diraja Seri Menanti. Lagu ''Berkatlah Yang di-Pertuan Besar''.', 'Tepat! Maklumat Negeri Sembilan kini lengkap dalam catatan kau, dan semua orang bersorak!'),
(NULL, 'e2_n3_s7', 'hint', 'Catat ibu negeri, bandar diraja dan lagu Melaka. Jata, bendera dan radio di gambar ini membantu kau ingat.', NULL, NULL),
(235, NULL, 'hint', 'Ingat kata kunci pokok Melaka. Jata, bendera dan radio di gambar ini menyimpan petunjuknya.', 'Melaka: asal nama, Pokok Melaka tempat Parameswara berehat. Ketua negeri Yang di-Pertua Negeri. Ibu negeri Bandar Melaka. Lagu ''Melaka Maju Jaya''.', 'Hebat! Melaka kini terukir kemas dalam ingatan kau.'),
(NULL, 'e2_n3_s8', 'hint', 'Buku catatan sedia? Ibu negeri, bandar diraja dan lagu Johor ada di sekeliling kau.', NULL, NULL),
(236, NULL, 'hint', 'Sst! Kata kunci hari ini ialah batu permata. Tengok jata, bendera dan radio dengan teliti.', 'Johor: asal nama, Perkataan Arab ''Jauhar'', iaitu batu permata bernilai. Ketua negeri Sultan. Ibu negeri Johor Bahru, bandar diraja Bandar Maharani. Lagu ''Lagu Bangsa Johor''.', 'Betul sekali! Jawapan kau membuat penduduk Johor tersenyum bangga.'),
(NULL, 'e2_n3_s9', 'hint', 'Catat ibu negeri, bandar diraja dan lagu Pahang. Jata, bendera dan radio di gambar ini membantu kau ingat.', NULL, NULL),
(237, NULL, 'hint', 'Petunjuk rahsia: pokok mahang. Jata, bendera dan radio di gambar ini tidak berbohong.', 'Pahang: asal nama, Pokok mahang, juga dikenali sebagai Inderapura. Ketua negeri Sultan. Ibu negeri Kuantan, bandar diraja Pekan. Lagu ''Allah Selamatkan Sultan Kami''.', 'Bagus! Satu lagi negeri berjaya kau takluki dengan ilmu!'),
(NULL, 'e2_n3_s10', 'hint', 'Buku catatan sedia? Ibu negeri, bandar diraja dan lagu Terengganu ada di sekeliling kau.', NULL, NULL),
(238, NULL, 'hint', 'Ingat kata kunci pelangi. Jata, bendera dan radio di gambar ini menyimpan petunjuknya.', 'Terengganu: asal nama, ''Taring anu'' (taring binatang liar) atau ''terang ganu'' (pelangi). Ketua negeri Sultan. Ibu negeri Kuala Terengganu. Lagu ''Selamat Sultan''.', 'Tepat! Maklumat Terengganu kini lengkap dalam catatan kau, dan semua orang bersorak!'),
(NULL, 'e2_n3_s11', 'hint', 'Catat ibu negeri, bandar diraja dan lagu Kelantan. Jata, bendera dan radio di gambar ini membantu kau ingat.', NULL, NULL),
(239, NULL, 'hint', 'Sst! Kata kunci hari ini ialah Ho-lan-tan. Tengok jata, bendera dan radio dengan teliti.', 'Kelantan: asal nama, Kilatan cahaya terang atau pokok gelam hutan. Ketua negeri Sultan. Ibu negeri Kota Bharu. Lagu ''Selamat Sultan''.', 'Hebat! Kelantan kini terukir kemas dalam ingatan kau.'),
(NULL, 'e2_n3_s12', 'hint', 'Buku catatan sedia? Ibu negeri, bandar diraja dan lagu Sabah ada di sekeliling kau.', NULL, NULL),
(240, NULL, 'hint', 'Petunjuk rahsia: pisang saba. Jata, bendera dan radio di gambar ini tidak berbohong.', 'Sabah: asal nama, Sejenis pisang, iaitu pisang saba atau pisang jaba. Ketua negeri Yang di-Pertua Negeri. Ibu negeri Kota Kinabalu. Lagu ''Sabah Tanah Airku''.', 'Betul sekali! Jawapan kau membuat penduduk Sabah tersenyum bangga.'),
(NULL, 'e2_n3_s13', 'hint', 'Catat ibu negeri, bandar diraja dan lagu Sarawak. Jata, bendera dan radio di gambar ini membantu kau ingat.', NULL, NULL),
(241, NULL, 'hint', 'Ingat kata kunci antimoni. Jata, bendera dan radio di gambar ini menyimpan petunjuknya.', 'Sarawak: asal nama, Sungai Sarawak, logam antimoni (cerava) atau ''serah kepada awak''. Ketua negeri Yang di-Pertua Negeri. Ibu negeri Kuching. Lagu ''Ibu Pertiwiku''.', 'Bagus! Satu lagi negeri berjaya kau takluki dengan ilmu!'),
(NULL, 'e2_n3_s14', 'hint', 'Buku catatan sedia? Ibu negeri, bandar diraja dan lagu Wilayah Persekutuan ada di sekeliling kau.', NULL, NULL),
(242, NULL, 'hint', 'Sst! Kata kunci hari ini ialah muara berlumpur. Tengok jata, bendera dan radio dengan teliti.', 'Wilayah Persekutuan: asal nama, Muara berlumpur (KL), labuhan (Labuan), sempena Tunku (Putrajaya). Ketua negeri Yang di-Pertuan Agong. Lagu ''Maju dan Sejahtera''.', 'Tepat! Maklumat Wilayah Persekutuan kini lengkap dalam catatan kau, dan semua orang bersorak!');
INSERT INTO DialogueLine (npcID, narrativeID, sceneID, dialogueLine, sequenceOrder) VALUES
(21, 201, NULL, 'Tahukah kau, {nama}? Setiap kali penglipur lara berhenti bercerita, satu nama negeri hilang daripada ingatan. Terima kasih kerana meminjamkan jiwa, kini nama dan warisan kita terus hidup!', 1),
(21, 201, NULL, 'Nama sesebuah negeri ialah wasiat nenek moyang. Selagi kita bercerita tentangnya, jati diri kita tidak akan pudar.', 2),
(21, 201, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penglipur lara tua yang menyimpan cerita asal usul nama negeri. Tikar mengkuang dibentang, cerita pun bermula! Dengarlah dengan telinganya dan bercakaplah dengan suaranya.', 3),
(NULL, 201, 'e2_n1_s1', 'Angin sawah menghembus padi yang menguning. Bendera Perlis berkibar di tiang kampung, jata negeri terpampang pada balai di tengah sawah, dan radio di atas meja mengalunkan lagu negeri.', 1),
(28, 201, 'e2_n1_s1', 'Eh, Tok Penglipur Lara! Berhenti sekejap sebelum lumpur sawah melekat di kaki Tok! Kami sedang berbalah ni: apakah asal usul nama Perlis?', 2),
(NULL, 201, 'e2_n1_s1', 'Hah, rapatkan duduk dan dengar baik-baik: Daripada perkataan Siam ''phrau loi'' (kelapa hanyut), perkataan tempatan ''peroleh'' atau tokoh Tok Perlis.', 3),
(28, 201, 'e2_n1_s1', 'Kelapa hanyut? Ha ha, patutlah! Selama ini saya angkat kelapa tepi parit tanpa tahu sejarahnya. Tok, siapa pula yang memayungi Perlis?', 4),
(NULL, 201, 'e2_n1_s1', 'Nah, ini yang ramai terlupa! Ketua negeri Perlis bergelar Raja.', 5),
(28, 201, 'e2_n1_s1', 'Dan di manakah ibu negerinya, Tok? Saya mahu catat dalam buku!', 6),
(NULL, 201, 'e2_n1_s1', 'Catat laju-laju! Ibu negerinya Kangar, dan bandar dirajanya Arau.', 7),
(28, 201, 'e2_n1_s1', 'Eh, dengar! Radio itu berbunyi, TING-TUNG! Lagu apakah itu, Tok?', 8),
(NULL, 201, 'e2_n1_s1', 'Dengar, itulah dia! Radio itu mengalunkan lagu negeri; tajuk lagunya belum dapat kita pastikan. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(28, 201, 'e2_n1_s1', 'Wah, padi pun macam mengangguk dengar cerita Tok! Mari ke pondok, saya belanja teh panas.', 10),
(NULL, 201, 'e2_n1_s2', 'Hamparan sawah padi berkilau di bawah langit senja. Bendera Kedah berkibar di hujung tiang, jata negeri terpampang pada rumah besar, dan alat muzik di beranda mengalunkan lagu negeri.', 1),
(28, 201, 'e2_n1_s2', 'Tok! Tok! Sini, sini! Cucu saya baru belajar nama negeri tapi saya sendiri tak pandai jawab. Apakah asal usul nama Kedah?', 2),
(NULL, 201, 'e2_n1_s2', 'Syyy! Ini bukan cerita calang-calang: Daripada ''Kheddah'' (perangkap gajah), ''Qadah'' dalam bahasa Arab (gelas berkaki) atau ''Kadaram'' dalam rujukan India.', 3),
(28, 201, 'e2_n1_s2', 'Perangkap gajah! Patutlah ada yang kata nama ini bunyi garang. Hebat betul! Tok, siapa pula yang memayungi Kedah?', 4),
(NULL, 201, 'e2_n1_s2', 'Soalan yang bagus! Ketua negeri Kedah bergelar Sultan.', 5),
(28, 201, 'e2_n1_s2', 'Ibu negerinya pula, Tok? Cepat, cepat, saya tak sabar!', 6),
(NULL, 201, 'e2_n1_s2', 'Pena sudah sedia? Ibu negerinya Alor Setar, dan bandar dirajanya Anak Bukit.', 7),
(28, 201, 'e2_n1_s2', 'Shhh! Radio itu mengalunkan lagu, Tok. Lagu negeri apakah itu?', 8),
(NULL, 201, 'e2_n1_s2', 'Jangan berhenti menyanyi! Lagu negerinya ialah ''Allah Selamatkan Sultan Mahkota''. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(28, 201, 'e2_n1_s2', 'Cucu saya ternganga, Tok! Esok dia mesti cerita pada kawan-kawan. Terima kasih, Tok!', 10),
(NULL, 201, 'e2_n1_s3', 'Bau garam dan angin laut singgah di jeti yang sibuk. Bendera Pulau Pinang berkibar di jeti, jata negeri terpampang pada gerbang batu, dan gramofon di tepi laut mengalunkan lagu negeri.', 1),
(30, 201, 'e2_n1_s3', 'Hoi, Tok Penglipur Lara! Duduk dulu atas tong ni sebelum bot berlepas! Pelanggan saya tanya, saya tak tahu: apakah asal usul nama Pulau Pinang?', 2),
(NULL, 201, 'e2_n1_s3', 'Tarik nafas dalam-dalam, kerana kisahnya begini: Sempena pokok pinang yang banyak tumbuh di pulau itu, yang dahulu dikenali sebagai Pulo Ka Satu atau Tanjong Penaga.', 3),
(30, 201, 'e2_n1_s3', 'Pokok pinang! Patutlah nama itu sesuai dengan pulau ini! Siapa pula yang memayungi Pulau Pinang?', 4),
(NULL, 201, 'e2_n1_s3', 'Dengar elok-elok, ini penting! Ketua negeri Pulau Pinang bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 5),
(30, 201, 'e2_n1_s3', 'Satu lagi, Tok: di manakah ibu negerinya dan bandar dirajanya?', 6),
(NULL, 201, 'e2_n1_s3', 'Ini mudah, tetapi ramai tersilap! Ibu negerinya Georgetown.', 7),
(30, 201, 'e2_n1_s3', 'Tok, tok! Radio itu berbunyi sendiri. Itu lagu apa?', 8),
(NULL, 201, 'e2_n1_s3', 'Hebat telinga kamu! Lagu negerinya ialah ''Untuk Negeri Kita''. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(30, 201, 'e2_n1_s3', 'Ha, sekarang saya boleh jawab pelancong yang bertanya tiap hari! Terima kasih, Tok. Jeti ini bergema dengan cerita Tok!', 10),
(NULL, 201, 'e2_n1_s4', 'Cahaya petang menyuluh halaman yang bersih disapu. Bendera Perak berkibar di tiang, jata negeri terpampang pada ukiran rumah, dan gramofon di atas meja mengalunkan lagu negeri.', 1),
(32, 201, 'e2_n1_s4', 'Ya Allah, Tok Penglipur Lara datang! Nenek tunggu dari pagi tadi, Tok. Cucu-cucu bertanya dan nenek buntu: apakah asal usul nama Perak?', 2),
(NULL, 201, 'e2_n1_s4', 'Hehe, ini rahsia orang tua-tua: Dikaitkan dengan kilatan ikan di dalam air atau warna bijih timah putih yang berkilat seperti perak.', 3),
(32, 201, 'e2_n1_s4', 'Kilauan perak! Ha, nenek patut sebut dari dulu. Cucu-cucu, dengar elok-elok! Tok, siapa pula yang memayungi Perak?', 4),
(NULL, 201, 'e2_n1_s4', 'Hah, jangan lupa yang ini! Ketua negeri Perak bergelar Sultan. Takhtanya berpindah secara bergilir mengikut sistem penggiliran yang unik.', 5),
(32, 201, 'e2_n1_s4', 'Dan di manakah ibu negerinya, Tok? Saya mahu catat dalam buku!', 6),
(NULL, 201, 'e2_n1_s4', 'Catat laju-laju! Ibu negerinya Ipoh, dan bandar dirajanya Kuala Kangsar.', 7),
(32, 201, 'e2_n1_s4', 'Eh, dengar! Radio itu berbunyi, TING-TUNG! Lagu apakah itu, Tok?', 8),
(NULL, 201, 'e2_n1_s4', 'Dengar, itulah dia! Lagu negerinya ialah ''Allah Lanjutkan Usia Sultan''. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(32, 201, 'e2_n1_s4', 'Hebat, Tok! Cucu-cucu nenek sudah tak berani nakal. Mari makan kuih dahulu!', 10),
(NULL, 201, 'e2_n1_s5', 'Air sungai mengalir tenang dan burung berkicau di tebing. Bendera Selangor berkibar di tiang, jata negeri terpampang pada pintu gerbang rumah, dan gramofon di atas meja mengalunkan lagu negeri.', 1),
(30, 201, 'e2_n1_s5', 'Tok! Tok Penglipur Lara! Pelanggan saya berbalah di kedai, semuanya bertanya benda sama: apakah asal usul nama Selangor?', 2),
(NULL, 201, 'e2_n1_s5', 'Hah, rapatkan duduk dan dengar baik-baik: Sempena Sungai Selangor, pokok mentagau di kuala sungai, atau sejenis serangga yang disebut selangur.', 3),
(30, 201, 'e2_n1_s5', 'Sungai, pokok, serangga? Banyaknya teori! Saya ingat satu cerita saja. Tok memang gudang cerita! Siapa pula yang memayungi Selangor?', 4),
(NULL, 201, 'e2_n1_s5', 'Nah, ini yang ramai terlupa! Ketua negeri Selangor bergelar Sultan.', 5),
(30, 201, 'e2_n1_s5', 'Ibu negerinya pula, Tok? Cepat, cepat, saya tak sabar!', 6),
(NULL, 201, 'e2_n1_s5', 'Pena sudah sedia? Ibu negerinya Shah Alam, dan bandar dirajanya Klang.', 7),
(30, 201, 'e2_n1_s5', 'Shhh! Radio itu mengalunkan lagu, Tok. Lagu negeri apakah itu?', 8),
(NULL, 201, 'e2_n1_s5', 'Jangan berhenti menyanyi! Lagu negerinya ialah ''Duli Yang Maha Mulia''. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(30, 201, 'e2_n1_s5', 'Pelanggan saya senyap semua, Tok! Ini baru namanya penglipur lara. Esok datang lagi, ya!', 10),
(NULL, 201, 'e2_n1_s6', 'Bumbung bergonjong rumah adat tegak di hujung halaman. Bendera Negeri Sembilan berkibar di tiang, jata negeri terpampang pada pintu pagar, dan gramofon di halaman mengalunkan lagu negeri.', 1),
(32, 201, 'e2_n1_s6', 'Tok Penglipur Lara, naiklah ke halaman! Nenek sedang membetulkan sirih tapi cucu bertanya soalan sukar: apakah asal usul nama Negeri Sembilan?', 2),
(NULL, 201, 'e2_n1_s6', 'Syyy! Ini bukan cerita calang-calang: Penyatuan sembilan luak asal seperti Sungai Ujong, Jelebu, Rembau dan Johol; perkataan negeri berasal daripada ''nagari''.', 3),
(32, 201, 'e2_n1_s6', 'Sembilan luak! Ha, ya betul, nenek pun ingat sekarang. Dan ''nagari'' bermaksud wilayah. Pandainya Tok! Siapa pula yang memayungi Negeri Sembilan?', 4),
(NULL, 201, 'e2_n1_s6', 'Soalan yang bagus! Ketua negeri Negeri Sembilan bergelar Yang di-Pertuan Besar. Beliau dipilih oleh Undang Yang Empat.', 5),
(32, 201, 'e2_n1_s6', 'Satu lagi, Tok: di manakah ibu negerinya dan bandar dirajanya?', 6),
(NULL, 201, 'e2_n1_s6', 'Ini mudah, tetapi ramai tersilap! Ibu negerinya Seremban, dan bandar dirajanya Seri Menanti.', 7),
(32, 201, 'e2_n1_s6', 'Tok, tok! Radio itu berbunyi sendiri. Itu lagu apa?', 8),
(NULL, 201, 'e2_n1_s6', 'Hebat telinga kamu! Lagu negerinya ialah ''Berkatlah Yang di-Pertuan Besar''. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(32, 201, 'e2_n1_s6', 'Cucu-cucu nenek ternganga macam ikan keli. Terima kasih, Tok! Marilah naik, nenek hidangkan masakan lemak.', 10),
(NULL, 201, 'e2_n1_s7', 'Bunyi sungai dan bayangan kubu lama menyambut pagi. Bendera Melaka berkibar di atas kubu, jata negeri terpampang pada papan kayu, dan gambus di atas tugu mengalunkan lagu negeri.', 1),
(30, 201, 'e2_n1_s7', 'Tok Penglipur Lara! Demi sejarah, singgahlah dahulu! Pelancong bertanya dan saya tak tahu jawab: apakah asal usul nama Melaka?', 2),
(NULL, 201, 'e2_n1_s7', 'Tarik nafas dalam-dalam, kerana kisahnya begini: Sempena pokok Melaka tempat Parameswara berehat, atau ''Malakat'' dalam rujukan Arab yang bermaksud pusat pedagang.', 3),
(30, 201, 'e2_n1_s7', 'Pokok Melaka! Tempat Parameswara berehat! Saya selalu lalu situ tapi tak pernah fikir. Hebat Tok! Siapa pula yang memayungi Melaka?', 4),
(NULL, 201, 'e2_n1_s7', 'Dengar elok-elok, ini penting! Ketua negeri Melaka bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 5),
(30, 201, 'e2_n1_s7', 'Dan di manakah ibu negerinya, Tok? Saya mahu catat dalam buku!', 6),
(NULL, 201, 'e2_n1_s7', 'Catat laju-laju! Ibu negerinya Bandar Melaka.', 7),
(30, 201, 'e2_n1_s7', 'Eh, dengar! Radio itu berbunyi, TING-TUNG! Lagu apakah itu, Tok?', 8),
(NULL, 201, 'e2_n1_s7', 'Dengar, itulah dia! Lagu negerinya ialah ''Melaka Maju Jaya''. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(30, 201, 'e2_n1_s7', 'Pelancong bertepuk tangan, Tok! Sungai Melaka pun macam mengalir lebih laju dengan semangat cerita itu.', 10),
(NULL, 201, 'e2_n1_s8', 'Angin petang menyapu permukaan sungai yang berkilat. Bendera Johor berkibar di tepi sungai, jata negeri terpampang pada pintu gerbang, dan gramofon di kedai kopi mengalunkan lagu negeri.', 1),
(30, 201, 'e2_n1_s8', 'Aduh, Tok Penglipur Lara! Tepat pada masanya! Kedai kopi saya hampir bergaduh sebab satu soalan: apakah asal usul nama Johor?', 2),
(NULL, 201, 'e2_n1_s8', 'Hehe, ini rahsia orang tua-tua: Daripada perkataan Arab ''Jauhar'' (batu permata bernilai), dan dikenali sebagai Ujung Tanah dalam Sulalatus Salatin.', 3),
(30, 201, 'e2_n1_s8', 'Batu permata! Patutlah Johor berkilau! Orang kedai kopi pun pasti terkejut. Tok, siapa pula yang memayungi Johor?', 4),
(NULL, 201, 'e2_n1_s8', 'Hah, jangan lupa yang ini! Ketua negeri Johor bergelar Sultan.', 5),
(30, 201, 'e2_n1_s8', 'Ibu negerinya pula, Tok? Cepat, cepat, saya tak sabar!', 6),
(NULL, 201, 'e2_n1_s8', 'Pena sudah sedia? Ibu negerinya Johor Bahru, dan bandar dirajanya Bandar Maharani.', 7),
(30, 201, 'e2_n1_s8', 'Shhh! Radio itu mengalunkan lagu, Tok. Lagu negeri apakah itu?', 8),
(NULL, 201, 'e2_n1_s8', 'Jangan berhenti menyanyi! Lagu negerinya ialah ''Lagu Bangsa Johor''. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(30, 201, 'e2_n1_s8', 'Seisi kedai kopi senyap, Tok! Kopi pun sejuk sebab semua dengar cerita Tok. Hebat!', 10),
(NULL, 201, 'e2_n1_s9', 'Kabus nipis naik dari sungai dan hutan di seberang. Bendera Pahang berkibar di tepi sungai, jata negeri terpampang pada rumah besar, dan radio di atas meja kayu mengalunkan lagu negeri.', 1),
(29, 201, 'e2_n1_s9', 'Hoi, Tok Penglipur Lara! Datuk saya tinggalkan catatan lama tapi saya tak boleh baca soalan pertamanya: apakah asal usul nama Pahang?', 2),
(NULL, 201, 'e2_n1_s9', 'Hah, rapatkan duduk dan dengar baik-baik: Diambil daripada nama pokok mahang, dan dikenali juga sebagai Inderapura dalam catatan lama.', 3),
(29, 201, 'e2_n1_s9', 'Pokok mahang! Dan Inderapura pun rupanya nama lamanya! Kabus pun macam tersenyum. Tok, siapa pula yang memayungi Pahang?', 4),
(NULL, 201, 'e2_n1_s9', 'Nah, ini yang ramai terlupa! Ketua negeri Pahang bergelar Sultan.', 5),
(29, 201, 'e2_n1_s9', 'Satu lagi, Tok: di manakah ibu negerinya dan bandar dirajanya?', 6),
(NULL, 201, 'e2_n1_s9', 'Ini mudah, tetapi ramai tersilap! Ibu negerinya Kuantan, dan bandar dirajanya Pekan.', 7),
(29, 201, 'e2_n1_s9', 'Tok, tok! Radio itu berbunyi sendiri. Itu lagu apa?', 8),
(NULL, 201, 'e2_n1_s9', 'Hebat telinga kamu! Lagu negerinya ialah ''Allah Selamatkan Sultan Kami''. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(29, 201, 'e2_n1_s9', 'Datuk saya pasti bangga di alam sana, Tok! Hutan seberang sungai pun senyap dengar cerita Tok.', 10),
(NULL, 201, 'e2_n1_s10', 'Ombak berbuih memukul pantai dan layang-layang camar berputar. Bendera Terengganu berkibar di tepi pantai, jata negeri terpampang pada dinding rumah, dan alat muzik di beranda mengalunkan lagu negeri.', 1),
(27, 201, 'e2_n1_s10', 'Tok Penglipur Lara! Sini, duduk atas perahu ini! Saya nelayan tapi tak pandai jawab soalan anak saya: apakah asal usul nama Terengganu?', 2),
(NULL, 201, 'e2_n1_s10', 'Syyy! Ini bukan cerita calang-calang: Daripada sebutan ''taring anu'' (taring harimau atau binatang liar) atau ''terang ganu'' yang bermaksud pelangi.', 3),
(27, 201, 'e2_n1_s10', 'Taring binatang atau pelangi! Dua-duanya cantik, Tok! Hampir terlepas jala saya kerana terkejut. Siapa pula yang memayungi Terengganu?', 4),
(NULL, 201, 'e2_n1_s10', 'Soalan yang bagus! Ketua negeri Terengganu bergelar Sultan.', 5),
(27, 201, 'e2_n1_s10', 'Dan di manakah ibu negerinya, Tok? Saya mahu catat dalam buku!', 6),
(NULL, 201, 'e2_n1_s10', 'Catat laju-laju! Ibu negerinya Kuala Terengganu.', 7),
(27, 201, 'e2_n1_s10', 'Eh, dengar! Radio itu berbunyi, TING-TUNG! Lagu apakah itu, Tok?', 8),
(NULL, 201, 'e2_n1_s10', 'Dengar, itulah dia! Lagu negerinya ialah ''Selamat Sultan''. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(27, 201, 'e2_n1_s10', 'Anak saya melompat gembira, Tok! Perahu ini bergoyang tak henti. Terima kasih banyak!', 10),
(NULL, 201, 'e2_n1_s11', 'Ukiran kayu berkilat di rumah tua yang harum dengan bunga. Bendera Kelantan berkibar di tiang, jata negeri terpampang pada gerbang rumah, dan rebana dan serunai di atas meja mengalunkan lagu negeri.', 1),
(32, 201, 'e2_n1_s11', 'Tok Penglipur Lara! Nenek sedang menyudahkan tikar ni, tapi cucu bertanya soalan yang nenek tak dapat jawab: apakah asal usul nama Kelantan?', 2),
(NULL, 201, 'e2_n1_s11', 'Tarik nafas dalam-dalam, kerana kisahnya begini: Sebutan ''kilatan'' (cahaya terang) atau nama pokok gelam hutan, dan disebut Ho-lan-tan dalam rujukan China.', 3),
(32, 201, 'e2_n1_s11', 'Kilatan cahaya atau pokok gelam hutan! Cantik betul ceritanya. Dan orang China menyebutnya Ho-lan-tan! Tok, siapa pula yang memayungi Kelantan?', 4),
(NULL, 201, 'e2_n1_s11', 'Dengar elok-elok, ini penting! Ketua negeri Kelantan bergelar Sultan.', 5),
(32, 201, 'e2_n1_s11', 'Ibu negerinya pula, Tok? Cepat, cepat, saya tak sabar!', 6),
(NULL, 201, 'e2_n1_s11', 'Pena sudah sedia? Ibu negerinya Kota Bharu.', 7),
(32, 201, 'e2_n1_s11', 'Shhh! Radio itu mengalunkan lagu, Tok. Lagu negeri apakah itu?', 8),
(NULL, 201, 'e2_n1_s11', 'Jangan berhenti menyanyi! Lagu negerinya ialah ''Selamat Sultan''. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(32, 201, 'e2_n1_s11', 'Cucu nenek terdiam, Tok! Jarang betul dia diam begini. Marilah makan dahulu.', 10),
(NULL, 201, 'e2_n1_s12', 'Air sungai berwarna teh mengalir lambat di bawah tebing. Bendera Sarawak berkibar tinggi, jata negeri terpampang pada pintu gerbang, dan alat muzik di atas tugu mengalunkan lagu negeri.', 1),
(34, 201, 'e2_n1_s12', 'Uy, Tok Penglipur Lara! Datang jauh sampai sini? Saya bangga dengan nama negeri saya tapi satu soalan membuntukan saya: apakah asal usul nama Sarawak?', 2),
(NULL, 201, 'e2_n1_s12', 'Hehe, ini rahsia orang tua-tua: Berasal daripada Sungai Sarawak, logam antimoni yang disebut cerava, atau dialog ''serah kepada awak''.', 3),
(34, 201, 'e2_n1_s12', 'Sungai, antimoni, atau ''serah kepada awak''! Banyak betul cerita! Saya mesti ceritakan pada kawan di bandar. Tok, siapa pula yang memayungi Sarawak?', 4),
(NULL, 201, 'e2_n1_s12', 'Hah, jangan lupa yang ini! Ketua negeri Sarawak bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 5),
(34, 201, 'e2_n1_s12', 'Satu lagi, Tok: di manakah ibu negerinya dan bandar dirajanya?', 6),
(NULL, 201, 'e2_n1_s12', 'Ini mudah, tetapi ramai tersilap! Ibu negerinya Kuching.', 7),
(34, 201, 'e2_n1_s12', 'Tok, tok! Radio itu berbunyi sendiri. Itu lagu apa?', 8),
(NULL, 201, 'e2_n1_s12', 'Hebat telinga kamu! Lagu negerinya ialah ''Ibu Pertiwiku''. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(34, 201, 'e2_n1_s12', 'Gempak, Tok! Sungai ini sendiri macam mengalir lebih laju mendengar cerita Tok.', 10),
(NULL, 201, 'e2_n1_s13', 'Angin teluk berhembus sambil gong kecil berdenting jauh. Bendera Sabah berkibar di tiang, jata negeri terpampang pada bangunan batu, dan alat muzik di pondok mengalunkan lagu negeri.', 1),
(33, 201, 'e2_n1_s13', 'Selamat datang, Tok Penglipur Lara! Duduk dahulu di pondok ini. Kami bawa nota dari kampung tapi tak pandai tafsir: apakah asal usul nama Sabah?', 2),
(NULL, 201, 'e2_n1_s13', 'Hah, rapatkan duduk dan dengar baik-baik: Diambil daripada sejenis pisang, iaitu pisang saba (pisang jaba).', 3),
(33, 201, 'e2_n1_s13', 'Pisang saba! Pisang jaba! Perut saya pun berbunyi mendengarnya. Hebat sungguh, Tok! Siapa pula yang memayungi Sabah?', 4),
(NULL, 201, 'e2_n1_s13', 'Nah, ini yang ramai terlupa! Ketua negeri Sabah bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 5),
(33, 201, 'e2_n1_s13', 'Dan di manakah ibu negerinya, Tok? Saya mahu catat dalam buku!', 6),
(NULL, 201, 'e2_n1_s13', 'Catat laju-laju! Ibu negerinya Kota Kinabalu.', 7),
(33, 201, 'e2_n1_s13', 'Eh, dengar! Radio itu berbunyi, TING-TUNG! Lagu apakah itu, Tok?', 8),
(NULL, 201, 'e2_n1_s13', 'Dengar, itulah dia! Lagu negerinya ialah ''Sabah Tanah Airku''. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(33, 201, 'e2_n1_s13', 'Seisi kampung bertepuk tangan, Tok! Gong pun berbunyi sendiri. Terima kasih banyak!', 10),
(NULL, 201, 'e2_n1_s14', 'Lampu bandar menyala dan bunyi trafik bersahut-sahutan. Bendera Wilayah Persekutuan berkibar di tiang, jata negeri terpampang pada gerbang batu, dan gramofon di atas tugu mengalunkan lagu negeri.', 1),
(38, 201, 'e2_n1_s14', 'Wah, Tok Penglipur Lara betul-betul wujud! Cikgu suruh buat kerja rumah tentang nama Wilayah Persekutuan tapi Google pun buntu: apakah asal usul namanya?', 2),
(NULL, 201, 'e2_n1_s14', 'Syyy! Ini bukan cerita calang-calang: Kuala Lumpur daripada muara sungai berlumpur akibat perlombongan bijih timah, Labuan daripada ''labuhan'', Putrajaya sempena Tunku Abdul Rahman Putra.', 3),
(38, 201, 'e2_n1_s14', 'Muara berlumpur, labuhan, dan nama Tunku! Tiga nama, tiga cerita! Boleh saya rakam? Tok, siapa pula yang memayungi Wilayah Persekutuan?', 4),
(NULL, 201, 'e2_n1_s14', 'Soalan yang bagus! Ketua negeri bagi tiga Wilayah Persekutuan ialah Yang di-Pertuan Agong.', 5),
(38, 201, 'e2_n1_s14', 'Adakah Wilayah Persekutuan ada ibu negeri sendiri, Tok? Saya hairan betul!', 6),
(NULL, 201, 'e2_n1_s14', 'Pena sudah sedia? Wilayah Persekutuan tidak mempunyai ibu negeri tersendiri; ketiga-tiganya ialah Kuala Lumpur, Labuan dan Putrajaya.', 7),
(38, 201, 'e2_n1_s14', 'Shhh! Radio itu mengalunkan lagu, Tok. Lagu negeri apakah itu?', 8),
(NULL, 201, 'e2_n1_s14', 'Jangan berhenti menyanyi! Lagu negerinya ialah ''Maju dan Sejahtera''. Jata, bendera dan lagu itulah lambang kebanggaan negeri.', 9),
(38, 201, 'e2_n1_s14', 'Kerja rumah saya selesai! Kawan-kawan mesti cemburu. Terima kasih, Tok! Boleh saya siarkan?', 10),
(22, 202, NULL, 'Payung hanya berguna jika dipegang dengan betul, {nama}. Kerana kau memegang payung negeri ini, gelaran dan adat kita tidak pudar. Daulat Tuanku, dan terima kasih!', 1),
(22, 202, NULL, 'Setiap gelaran ketua negeri membawa sejarah dan tanggungjawabnya sendiri. Menghormatinya bermakna menghormati warisan negara kita.', 2),
(22, 202, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, ketua sebuah negeri beraja. Gamelan berbunyi, panji berkibar, dan ketua-ketua negeri lain menanti. Lihat dengan matanya dan bertitahlah dengan suaranya!', 3),
(NULL, 202, 'e2_n2_s1', 'Angin petang menyapu permukaan sungai yang berkilat. Bendera Johor berkibar di tepi sungai, jata negeri terpampang pada pintu gerbang, dan gramofon di kedai kopi mengalunkan lagu negeri.', 1),
(22, 202, 'e2_n2_s1', 'Selamat datang ke Johor, Tuanku! Angin petang menyambut Tuanku di tepi sungai. Soalan pembuka: tahukah Tuanku gelaran ketua negeri kami?', 2),
(NULL, 202, 'e2_n2_s1', 'Hmm, beta mahu melihat jata itu dahulu. Gelaran bukan sekadar nama; ia membawa sejarah.', 3),
(22, 202, 'e2_n2_s1', 'Demikianlah, Tuanku. Ketua negeri Johor bergelar Sultan.', 4),
(NULL, 202, 'e2_n2_s1', 'Dan nama Johor sendiri, dari manakah asalnya? Beta terlalu ingin tahu!', 5),
(22, 202, 'e2_n2_s1', 'Menurut cerita lama, daripada perkataan Arab ''Jauhar'' (batu permata bernilai), dan dikenali sebagai Ujung Tanah dalam Sulalatus Salatin.', 6),
(NULL, 202, 'e2_n2_s1', 'Wah, menarik sekali! Beta tidak menyangka cerita nama itu begitu. Dan ibu negeri serta bandar dirajanya pula?', 7),
(22, 202, 'e2_n2_s1', 'Ibu negerinya Johor Bahru, dan bandar dirajanya Bandar Maharani.', 8),
(NULL, 202, 'e2_n2_s1', 'Dengar! Radio itu berbunyi, dan beta kenal bunyinya. Lagu apakah itu?', 9),
(22, 202, 'e2_n2_s1', 'Lagu negerinya ialah ''Lagu Bangsa Johor''.', 10),
(NULL, 202, 'e2_n2_s1', 'Terima kasih, Tuanku. Beta sudah mencatat semuanya dalam hati.', 11),
(22, 202, 'e2_n2_s1', 'Semoga Tuanku mengingati Johor seperti batu permata, berkilau dalam ingatan.', 12),
(NULL, 202, 'e2_n2_s2', 'Hamparan sawah padi berkilau di bawah langit senja. Bendera Kedah berkibar di hujung tiang, jata negeri terpampang pada rumah besar, dan alat muzik di beranda mengalunkan lagu negeri.', 1),
(22, 202, 'e2_n2_s2', 'Selamat datang, Tuanku! Sawah Kedah sedang berkilau menyambut kunjungan Tuanku. Cuba teka: apakah gelaran ketua negeri kami?', 2),
(NULL, 202, 'e2_n2_s2', 'Beta perhatikan bendera itu berkibar megah. Biar beta cuba teka dahulu...', 3),
(22, 202, 'e2_n2_s2', 'Tepat pada pertanyaan Tuanku. Ketua negeri Kedah bergelar Sultan.', 4),
(NULL, 202, 'e2_n2_s2', 'Apakah pula sejarah nama Kedah? Ceritakanlah, beta sedia mendengar!', 5),
(22, 202, 'e2_n2_s2', 'Menurut cerita lama, daripada ''Kheddah'' (perangkap gajah), ''Qadah'' dalam bahasa Arab (gelas berkaki) atau ''Kadaram'' dalam rujukan India.', 6),
(NULL, 202, 'e2_n2_s2', 'Subhanallah, ada rupanya! Beta suka cerita begini. Di manakah ibu negerinya?', 7),
(22, 202, 'e2_n2_s2', 'Ibu negerinya Alor Setar, dan bandar dirajanya Anak Bukit.', 8),
(NULL, 202, 'e2_n2_s2', 'Alunan itu merdu sekali! Lagu apakah yang dimainkan di radio itu?', 9),
(22, 202, 'e2_n2_s2', 'Lagu negerinya ialah ''Allah Selamatkan Sultan Mahkota''.', 10),
(NULL, 202, 'e2_n2_s2', 'Alhamdulillah, hari ini beta bertambah ilmu tentang warisan negeri.', 11),
(22, 202, 'e2_n2_s2', 'Semoga Tuanku bawa pulang cerita Kedah, dan sebutkan nama Kedah dengan bangga!', 12),
(NULL, 202, 'e2_n2_s3', 'Ukiran kayu berkilat di rumah tua yang harum dengan bunga. Bendera Kelantan berkibar di tiang, jata negeri terpampang pada gerbang rumah, dan rebana dan serunai di atas meja mengalunkan lagu negeri.', 1),
(22, 202, 'e2_n2_s3', 'Selamat datang ke Kelantan, Tuanku! Ukiran kayu rumah ini berkilat menyambut Tuanku. Soalan pembuka: tahukah Tuanku gelaran ketua negeri kami?', 2),
(NULL, 202, 'e2_n2_s3', 'Menarik! Beta sudah lama ingin tahu tentang perkara ini.', 3),
(22, 202, 'e2_n2_s3', 'Itulah jawapannya, Tuanku. Ketua negeri Kelantan bergelar Sultan.', 4),
(NULL, 202, 'e2_n2_s3', 'Nama Kelantan bunyinya indah. Bagaimana ia bermula?', 5),
(22, 202, 'e2_n2_s3', 'Menurut cerita lama, sebutan ''kilatan'' (cahaya terang) atau nama pokok gelam hutan, dan disebut Ho-lan-tan dalam rujukan China.', 6),
(NULL, 202, 'e2_n2_s3', 'Hmm, menarik! Beta akan ingat itu. Ibu negeri dan bandar dirajanya pula di mana?', 7),
(22, 202, 'e2_n2_s3', 'Ibu negerinya Kota Bharu.', 8),
(NULL, 202, 'e2_n2_s3', 'Ada lagu di radio itu! Beta pasti ia lagu negeri. Apakah tajuknya?', 9),
(22, 202, 'e2_n2_s3', 'Lagu negerinya ialah ''Selamat Sultan''.', 10),
(NULL, 202, 'e2_n2_s3', 'Beta pulang dengan hati yang puas. Daulat!', 11),
(22, 202, 'e2_n2_s3', 'Semoga Tuanku mengenang Kelantan melalui ukiran dan cerita yang sampai ke telinga.', 12),
(NULL, 202, 'e2_n2_s4', 'Kabus nipis naik dari sungai dan hutan di seberang. Bendera Pahang berkibar di tepi sungai, jata negeri terpampang pada rumah besar, dan radio di atas meja kayu mengalunkan lagu negeri.', 1),
(22, 202, 'e2_n2_s4', 'Selamat datang ke Pahang, Tuanku! Kabus sungai ini menyambut Tuanku dengan tenang. Soalan pembuka: tahukah Tuanku gelaran ketua negeri kami?', 2),
(NULL, 202, 'e2_n2_s4', 'Hmm, beta mahu melihat jata itu dahulu. Gelaran bukan sekadar nama; ia membawa sejarah.', 3),
(22, 202, 'e2_n2_s4', 'Demikianlah, Tuanku. Ketua negeri Pahang bergelar Sultan.', 4),
(NULL, 202, 'e2_n2_s4', 'Dan nama Pahang sendiri, dari manakah asalnya? Beta terlalu ingin tahu!', 5),
(22, 202, 'e2_n2_s4', 'Menurut cerita lama, diambil daripada nama pokok mahang, dan dikenali juga sebagai Inderapura dalam catatan lama.', 6),
(NULL, 202, 'e2_n2_s4', 'Wah, menarik sekali! Beta tidak menyangka cerita nama itu begitu. Dan ibu negeri serta bandar dirajanya pula?', 7),
(22, 202, 'e2_n2_s4', 'Ibu negerinya Kuantan, dan bandar dirajanya Pekan.', 8),
(NULL, 202, 'e2_n2_s4', 'Dengar! Radio itu berbunyi, dan beta kenal bunyinya. Lagu apakah itu?', 9),
(22, 202, 'e2_n2_s4', 'Lagu negerinya ialah ''Allah Selamatkan Sultan Kami''.', 10),
(NULL, 202, 'e2_n2_s4', 'Terima kasih, Tuanku. Beta sudah mencatat semuanya dalam hati.', 11),
(22, 202, 'e2_n2_s4', 'Semoga Tuanku mengenang Pahang bila kabus pagi naik dari sungai.', 12),
(NULL, 202, 'e2_n2_s5', 'Cahaya petang menyuluh halaman yang bersih disapu. Bendera Perak berkibar di tiang, jata negeri terpampang pada ukiran rumah, dan gramofon di atas meja mengalunkan lagu negeri.', 1),
(22, 202, 'e2_n2_s5', 'Selamat datang ke Perak, Tuanku! Halaman ini disapu bersih sejak subuh. Soalan pembuka: tahukah Tuanku gelaran ketua negeri kami?', 2),
(NULL, 202, 'e2_n2_s5', 'Beta perhatikan bendera itu berkibar megah. Biar beta cuba teka dahulu...', 3),
(22, 202, 'e2_n2_s5', 'Tepat pada pertanyaan Tuanku. Ketua negeri Perak bergelar Sultan. Takhtanya berpindah secara bergilir mengikut sistem penggiliran yang unik.', 4),
(NULL, 202, 'e2_n2_s5', 'Apakah pula sejarah nama Perak? Ceritakanlah, beta sedia mendengar!', 5),
(22, 202, 'e2_n2_s5', 'Menurut cerita lama, dikaitkan dengan kilatan ikan di dalam air atau warna bijih timah putih yang berkilat seperti perak.', 6),
(NULL, 202, 'e2_n2_s5', 'Subhanallah, ada rupanya! Beta suka cerita begini. Di manakah ibu negerinya?', 7),
(22, 202, 'e2_n2_s5', 'Ibu negerinya Ipoh, dan bandar dirajanya Kuala Kangsar.', 8),
(NULL, 202, 'e2_n2_s5', 'Alunan itu merdu sekali! Lagu apakah yang dimainkan di radio itu?', 9),
(22, 202, 'e2_n2_s5', 'Lagu negerinya ialah ''Allah Lanjutkan Usia Sultan''.', 10),
(NULL, 202, 'e2_n2_s5', 'Alhamdulillah, hari ini beta bertambah ilmu tentang warisan negeri.', 11),
(22, 202, 'e2_n2_s5', 'Semoga Tuanku puas bertandang. Kuih sudah dihidang, jangan balik begitu sahaja!', 12),
(NULL, 202, 'e2_n2_s6', 'Air sungai mengalir tenang dan burung berkicau di tebing. Bendera Selangor berkibar di tiang, jata negeri terpampang pada pintu gerbang rumah, dan gramofon di atas meja mengalunkan lagu negeri.', 1),
(22, 202, 'e2_n2_s6', 'Selamat datang ke Selangor, Tuanku! Kicauan burung sungai menyambut kedatangan Tuanku. Soalan pembuka: tahukah Tuanku gelaran ketua negeri kami?', 2),
(NULL, 202, 'e2_n2_s6', 'Menarik! Beta sudah lama ingin tahu tentang perkara ini.', 3),
(22, 202, 'e2_n2_s6', 'Itulah jawapannya, Tuanku. Ketua negeri Selangor bergelar Sultan.', 4),
(NULL, 202, 'e2_n2_s6', 'Nama Selangor bunyinya indah. Bagaimana ia bermula?', 5),
(22, 202, 'e2_n2_s6', 'Menurut cerita lama, sempena Sungai Selangor, pokok mentagau di kuala sungai, atau sejenis serangga yang disebut selangur.', 6),
(NULL, 202, 'e2_n2_s6', 'Hmm, menarik! Beta akan ingat itu. Ibu negeri dan bandar dirajanya pula di mana?', 7),
(22, 202, 'e2_n2_s6', 'Ibu negerinya Shah Alam, dan bandar dirajanya Klang.', 8),
(NULL, 202, 'e2_n2_s6', 'Ada lagu di radio itu! Beta pasti ia lagu negeri. Apakah tajuknya?', 9),
(22, 202, 'e2_n2_s6', 'Lagu negerinya ialah ''Duli Yang Maha Mulia''.', 10),
(NULL, 202, 'e2_n2_s6', 'Beta pulang dengan hati yang puas. Daulat!', 11),
(22, 202, 'e2_n2_s6', 'Semoga Tuanku suka Selangor. Sungai ini sentiasa terbuka untuk Tuanku berehat.', 12),
(NULL, 202, 'e2_n2_s7', 'Ombak berbuih memukul pantai dan layang-layang camar berputar. Bendera Terengganu berkibar di tepi pantai, jata negeri terpampang pada dinding rumah, dan alat muzik di beranda mengalunkan lagu negeri.', 1),
(22, 202, 'e2_n2_s7', 'Selamat datang ke Terengganu, Tuanku! Ombak berbuih menyambut Tuanku di pantai. Soalan pembuka: tahukah Tuanku gelaran ketua negeri kami?', 2),
(NULL, 202, 'e2_n2_s7', 'Hmm, beta mahu melihat jata itu dahulu. Gelaran bukan sekadar nama; ia membawa sejarah.', 3),
(22, 202, 'e2_n2_s7', 'Demikianlah, Tuanku. Ketua negeri Terengganu bergelar Sultan.', 4),
(NULL, 202, 'e2_n2_s7', 'Dan nama Terengganu sendiri, dari manakah asalnya? Beta terlalu ingin tahu!', 5),
(22, 202, 'e2_n2_s7', 'Menurut cerita lama, daripada sebutan ''taring anu'' (taring harimau atau binatang liar) atau ''terang ganu'' yang bermaksud pelangi.', 6),
(NULL, 202, 'e2_n2_s7', 'Wah, menarik sekali! Beta tidak menyangka cerita nama itu begitu. Dan ibu negeri serta bandar dirajanya pula?', 7),
(22, 202, 'e2_n2_s7', 'Ibu negerinya Kuala Terengganu.', 8),
(NULL, 202, 'e2_n2_s7', 'Dengar! Radio itu berbunyi, dan beta kenal bunyinya. Lagu apakah itu?', 9),
(22, 202, 'e2_n2_s7', 'Lagu negerinya ialah ''Selamat Sultan''.', 10),
(NULL, 202, 'e2_n2_s7', 'Terima kasih, Tuanku. Beta sudah mencatat semuanya dalam hati.', 11),
(22, 202, 'e2_n2_s7', 'Semoga Tuanku membawa pulang bunyi ombak Terengganu dalam ingatan.', 12),
(NULL, 202, 'e2_n2_s8', 'Angin sawah menghembus padi yang menguning. Bendera Perlis berkibar di tiang kampung, jata negeri terpampang pada balai di tengah sawah, dan radio di atas meja mengalunkan lagu negeri.', 1),
(23, 202, 'e2_n2_s8', 'Selamat datang ke Perlis, Tuanku! Angin sawah pun berhenti menyambut. Soalan pertama: tahukah Tuanku gelaran ketua negeri di sini?', 2),
(NULL, 202, 'e2_n2_s8', 'Beta perhatikan bendera itu berkibar megah. Biar beta cuba teka dahulu...', 3),
(23, 202, 'e2_n2_s8', 'Tepat pada pertanyaan Tuanku. Ketua negeri Perlis bergelar Raja.', 4),
(NULL, 202, 'e2_n2_s8', 'Apakah pula sejarah nama Perlis? Ceritakanlah, beta sedia mendengar!', 5),
(23, 202, 'e2_n2_s8', 'Menurut cerita lama, daripada perkataan Siam ''phrau loi'' (kelapa hanyut), perkataan tempatan ''peroleh'' atau tokoh Tok Perlis.', 6),
(NULL, 202, 'e2_n2_s8', 'Subhanallah, ada rupanya! Beta suka cerita begini. Di manakah ibu negerinya?', 7),
(23, 202, 'e2_n2_s8', 'Ibu negerinya Kangar, dan bandar dirajanya Arau.', 8),
(NULL, 202, 'e2_n2_s8', 'Alunan itu merdu sekali! Lagu apakah yang dimainkan di radio itu?', 9),
(23, 202, 'e2_n2_s8', 'Radio itu mengalunkan lagu negeri; tajuk lagunya belum dapat kita pastikan.', 10),
(NULL, 202, 'e2_n2_s8', 'Alhamdulillah, hari ini beta bertambah ilmu tentang warisan negeri.', 11),
(23, 202, 'e2_n2_s8', 'Perlis kecil, Tuanku, tetapi ceritanya besar. Singgahlah lagi bila padi menguning!', 12),
(NULL, 202, 'e2_n2_s9', 'Bumbung bergonjong rumah adat tegak di hujung halaman. Bendera Negeri Sembilan berkibar di tiang, jata negeri terpampang pada pintu pagar, dan gramofon di halaman mengalunkan lagu negeri.', 1),
(24, 202, 'e2_n2_s9', 'Selamat datang ke Negeri Sembilan, Tuanku! Bumbung gonjong ini menjadi saksi kunjungan Tuanku. Soalan pembuka: tahukah Tuanku gelaran ketua negeri kami?', 2),
(NULL, 202, 'e2_n2_s9', 'Menarik! Beta sudah lama ingin tahu tentang perkara ini.', 3),
(24, 202, 'e2_n2_s9', 'Itulah jawapannya, Tuanku. Ketua negeri Negeri Sembilan bergelar Yang di-Pertuan Besar. Beliau dipilih oleh Undang Yang Empat.', 4),
(NULL, 202, 'e2_n2_s9', 'Nama Negeri Sembilan bunyinya indah. Bagaimana ia bermula?', 5),
(24, 202, 'e2_n2_s9', 'Menurut cerita lama, penyatuan sembilan luak asal seperti Sungai Ujong, Jelebu, Rembau dan Johol; perkataan negeri berasal daripada ''nagari''.', 6),
(NULL, 202, 'e2_n2_s9', 'Hmm, menarik! Beta akan ingat itu. Ibu negeri dan bandar dirajanya pula di mana?', 7),
(24, 202, 'e2_n2_s9', 'Ibu negerinya Seremban, dan bandar dirajanya Seri Menanti.', 8),
(NULL, 202, 'e2_n2_s9', 'Ada lagu di radio itu! Beta pasti ia lagu negeri. Apakah tajuknya?', 9),
(24, 202, 'e2_n2_s9', 'Lagu negerinya ialah ''Berkatlah Yang di-Pertuan Besar''.', 10),
(NULL, 202, 'e2_n2_s9', 'Beta pulang dengan hati yang puas. Daulat!', 11),
(24, 202, 'e2_n2_s9', 'Moga Tuanku mengingati Negeri Sembilan dengan bumbung gonjong dan sembilan luaknya!', 12),
(NULL, 202, 'e2_n2_s10', 'Bunyi sungai dan bayangan kubu lama menyambut pagi. Bendera Melaka berkibar di atas kubu, jata negeri terpampang pada papan kayu, dan gambus di atas tugu mengalunkan lagu negeri.', 1),
(25, 202, 'e2_n2_s10', 'Selamat datang ke Melaka, Tuanku! Bayangan kubu lama berdiri menyambut Tuanku. Soalan pembuka: tahukah Tuanku gelaran ketua negeri kami?', 2),
(NULL, 202, 'e2_n2_s10', 'Hmm, beta mahu melihat jata itu dahulu. Gelaran bukan sekadar nama; ia membawa sejarah.', 3),
(25, 202, 'e2_n2_s10', 'Demikianlah, Tuanku. Ketua negeri Melaka bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 4),
(NULL, 202, 'e2_n2_s10', 'Dan nama Melaka sendiri, dari manakah asalnya? Beta terlalu ingin tahu!', 5),
(25, 202, 'e2_n2_s10', 'Menurut cerita lama, sempena pokok Melaka tempat Parameswara berehat, atau ''Malakat'' dalam rujukan Arab yang bermaksud pusat pedagang.', 6),
(NULL, 202, 'e2_n2_s10', 'Wah, menarik sekali! Beta tidak menyangka cerita nama itu begitu. Dan ibu negeri serta bandar dirajanya pula?', 7),
(25, 202, 'e2_n2_s10', 'Ibu negerinya Bandar Melaka.', 8),
(NULL, 202, 'e2_n2_s10', 'Dengar! Radio itu berbunyi, dan beta kenal bunyinya. Lagu apakah itu?', 9),
(25, 202, 'e2_n2_s10', 'Lagu negerinya ialah ''Melaka Maju Jaya''.', 10),
(NULL, 202, 'e2_n2_s10', 'Terima kasih, Tuanku. Beta sudah mencatat semuanya dalam hati.', 11),
(25, 202, 'e2_n2_s10', 'Semoga Tuanku membawa semangat Melaka bersama. Kubu lama ini sentiasa menunggu kedatangan Tuanku.', 12),
(NULL, 202, 'e2_n2_s11', 'Bau garam dan angin laut singgah di jeti yang sibuk. Bendera Pulau Pinang berkibar di jeti, jata negeri terpampang pada gerbang batu, dan gramofon di tepi laut mengalunkan lagu negeri.', 1),
(25, 202, 'e2_n2_s11', 'Selamat datang ke Pulau Pinang, Tuanku! Bunyi pekikan burung camar pun bagai menyambut. Soalan pembuka: tahukah Tuanku gelaran ketua negeri kami?', 2),
(NULL, 202, 'e2_n2_s11', 'Beta perhatikan bendera itu berkibar megah. Biar beta cuba teka dahulu...', 3),
(25, 202, 'e2_n2_s11', 'Tepat pada pertanyaan Tuanku. Ketua negeri Pulau Pinang bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 4),
(NULL, 202, 'e2_n2_s11', 'Apakah pula sejarah nama Pulau Pinang? Ceritakanlah, beta sedia mendengar!', 5),
(25, 202, 'e2_n2_s11', 'Menurut cerita lama, sempena pokok pinang yang banyak tumbuh di pulau itu, yang dahulu dikenali sebagai Pulo Ka Satu atau Tanjong Penaga.', 6),
(NULL, 202, 'e2_n2_s11', 'Subhanallah, ada rupanya! Beta suka cerita begini. Di manakah ibu negerinya?', 7),
(25, 202, 'e2_n2_s11', 'Ibu negerinya Georgetown.', 8),
(NULL, 202, 'e2_n2_s11', 'Alunan itu merdu sekali! Lagu apakah yang dimainkan di radio itu?', 9),
(25, 202, 'e2_n2_s11', 'Lagu negerinya ialah ''Untuk Negeri Kita''.', 10),
(NULL, 202, 'e2_n2_s11', 'Alhamdulillah, hari ini beta bertambah ilmu tentang warisan negeri.', 11),
(25, 202, 'e2_n2_s11', 'Pulau ini kecil, Tuanku, tetapi hati kami besar. Semoga Tuanku singgah lagi sebelum bot terakhir berlepas.', 12),
(NULL, 202, 'e2_n2_s12', 'Angin teluk berhembus sambil gong kecil berdenting jauh. Bendera Sabah berkibar di tiang, jata negeri terpampang pada bangunan batu, dan alat muzik di pondok mengalunkan lagu negeri.', 1),
(25, 202, 'e2_n2_s12', 'Selamat datang ke Sabah, Tuanku! Angin teluk menyambut Tuanku dengan alunan gong. Soalan pembuka: tahukah Tuanku gelaran ketua negeri kami?', 2),
(NULL, 202, 'e2_n2_s12', 'Menarik! Beta sudah lama ingin tahu tentang perkara ini.', 3),
(25, 202, 'e2_n2_s12', 'Itulah jawapannya, Tuanku. Ketua negeri Sabah bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 4),
(NULL, 202, 'e2_n2_s12', 'Nama Sabah bunyinya indah. Bagaimana ia bermula?', 5),
(25, 202, 'e2_n2_s12', 'Menurut cerita lama, diambil daripada sejenis pisang, iaitu pisang saba (pisang jaba).', 6),
(NULL, 202, 'e2_n2_s12', 'Hmm, menarik! Beta akan ingat itu. Ibu negeri dan bandar dirajanya pula di mana?', 7),
(25, 202, 'e2_n2_s12', 'Ibu negerinya Kota Kinabalu.', 8),
(NULL, 202, 'e2_n2_s12', 'Ada lagu di radio itu! Beta pasti ia lagu negeri. Apakah tajuknya?', 9),
(25, 202, 'e2_n2_s12', 'Lagu negerinya ialah ''Sabah Tanah Airku''.', 10),
(NULL, 202, 'e2_n2_s12', 'Beta pulang dengan hati yang puas. Daulat!', 11),
(25, 202, 'e2_n2_s12', 'Semoga Tuanku membawa pulang hembusan angin teluk Sabah dalam ingatan.', 12),
(NULL, 202, 'e2_n2_s13', 'Air sungai berwarna teh mengalir lambat di bawah tebing. Bendera Sarawak berkibar tinggi, jata negeri terpampang pada pintu gerbang, dan alat muzik di atas tugu mengalunkan lagu negeri.', 1),
(25, 202, 'e2_n2_s13', 'Selamat datang ke Sarawak, Tuanku! Sungai ini menyambut Tuanku dengan tenang. Soalan pembuka: tahukah Tuanku gelaran ketua negeri kami?', 2),
(NULL, 202, 'e2_n2_s13', 'Hmm, beta mahu melihat jata itu dahulu. Gelaran bukan sekadar nama; ia membawa sejarah.', 3),
(25, 202, 'e2_n2_s13', 'Demikianlah, Tuanku. Ketua negeri Sarawak bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 4),
(NULL, 202, 'e2_n2_s13', 'Dan nama Sarawak sendiri, dari manakah asalnya? Beta terlalu ingin tahu!', 5),
(25, 202, 'e2_n2_s13', 'Menurut cerita lama, berasal daripada Sungai Sarawak, logam antimoni yang disebut cerava, atau dialog ''serah kepada awak''.', 6),
(NULL, 202, 'e2_n2_s13', 'Wah, menarik sekali! Beta tidak menyangka cerita nama itu begitu. Dan ibu negeri serta bandar dirajanya pula?', 7),
(25, 202, 'e2_n2_s13', 'Ibu negerinya Kuching.', 8),
(NULL, 202, 'e2_n2_s13', 'Dengar! Radio itu berbunyi, dan beta kenal bunyinya. Lagu apakah itu?', 9),
(25, 202, 'e2_n2_s13', 'Lagu negerinya ialah ''Ibu Pertiwiku''.', 10),
(NULL, 202, 'e2_n2_s13', 'Terima kasih, Tuanku. Beta sudah mencatat semuanya dalam hati.', 11),
(25, 202, 'e2_n2_s13', 'Semoga Tuanku membawa nama Sarawak jauh ke seberang laut dan kembali lagi.', 12),
(NULL, 202, 'e2_n2_s14', 'Lampu bandar menyala dan bunyi trafik bersahut-sahutan. Bendera Wilayah Persekutuan berkibar di tiang, jata negeri terpampang pada gerbang batu, dan gramofon di atas tugu mengalunkan lagu negeri.', 1),
(38, 202, 'e2_n2_s14', 'Selamat datang ke ibu kota, Tuanku! Lampu bandar menyala menyambut Tuanku. Soalan pembuka: tahukah Tuanku gelaran ketua negeri bagi tiga Wilayah Persekutuan?', 2),
(NULL, 202, 'e2_n2_s14', 'Beta perhatikan bendera itu berkibar megah. Biar beta cuba teka dahulu...', 3),
(38, 202, 'e2_n2_s14', 'Tepat pada pertanyaan Tuanku. Ketua negeri bagi tiga Wilayah Persekutuan ialah Yang di-Pertuan Agong.', 4),
(NULL, 202, 'e2_n2_s14', 'Apakah pula sejarah nama Wilayah Persekutuan? Ceritakanlah, beta sedia mendengar!', 5),
(38, 202, 'e2_n2_s14', 'Menurut cerita lama, kuala Lumpur daripada muara sungai berlumpur akibat perlombongan bijih timah, Labuan daripada ''labuhan'', Putrajaya sempena Tunku Abdul Rahman Putra.', 6),
(NULL, 202, 'e2_n2_s14', 'Menarik sekali! Tetapi adakah Wilayah Persekutuan mempunyai ibu negeri sendiri?', 7),
(38, 202, 'e2_n2_s14', 'Wilayah Persekutuan tidak mempunyai ibu negeri tersendiri; ketiga-tiganya ialah Kuala Lumpur, Labuan dan Putrajaya.', 8),
(NULL, 202, 'e2_n2_s14', 'Alunan itu merdu sekali! Lagu apakah yang dimainkan di radio itu?', 9),
(38, 202, 'e2_n2_s14', 'Lagu negerinya ialah ''Maju dan Sejahtera''.', 10),
(NULL, 202, 'e2_n2_s14', 'Alhamdulillah, hari ini beta bertambah ilmu tentang warisan negeri.', 11),
(38, 202, 'e2_n2_s14', 'Semoga Tuanku suka kota ini. Lampu bandar tidak pernah tidur untuk menyambut Tuanku!', 12),
(26, 203, NULL, 'Setiap negeri yang kau catat ialah satu lagu yang tidak akan senyap, {nama}. Terima kasih kerana mengembara bersamaku, kini ingatan tentang tanah air lebih terang!', 1),
(26, 203, NULL, 'Ibu negeri, bandar diraja dan lagu negeri ialah lambang kebanggaan setiap negeri. Mengenalinya ialah langkah pertama untuk mencintai tanah air.', 2),
(26, 203, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pengembara yang menjelajah seluruh tanah air dengan buku catatan di tangan. Beg digalas, kasut diikat, jejak bermula! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(NULL, 203, 'e2_n3_s1', 'Angin sawah menghembus padi yang menguning. Bendera Perlis berkibar di tiang kampung, jata negeri terpampang pada balai di tengah sawah, dan radio di atas meja mengalunkan lagu negeri.', 1),
(28, 203, 'e2_n3_s1', 'Pengembara! Jangan pijak batas sawah saya! Anda mencari ibu negeri Perlis, ya? Sudah tahu jawapannya?', 2),
(NULL, 203, 'e2_n3_s1', 'Belum! Tetapi pena sudah tajam dan buku catatan terbuka lebar. Ceritakanlah!', 3),
(28, 203, 'e2_n3_s1', 'Catatlah! Ibu negerinya Kangar, dan bandar dirajanya Arau.', 4),
(NULL, 203, 'e2_n3_s1', 'Dan radio itu berbunyi sendiri! Lagu negeri apakah yang berkumandang itu?', 5),
(28, 203, 'e2_n3_s1', 'Radio itu mengalunkan lagu negeri; tajuk lagunya belum dapat kita pastikan.', 6),
(NULL, 203, 'e2_n3_s1', 'Satu lagi untuk buku catatan: siapakah ketua negerinya, dan dari mana nama negeri ini bermula?', 7),
(28, 203, 'e2_n3_s1', 'Ketua negeri Perlis bergelar Raja.', 8),
(28, 203, 'e2_n3_s1', 'Dan nama negeri ini pula? Perkataan Siam ''phrau loi'', iaitu kelapa hanyut.', 9),
(NULL, 203, 'e2_n3_s1', 'Sudah lengkap! Dakwat pun hampir kering, tetapi hati saya penuh.', 10),
(28, 203, 'e2_n3_s1', 'Itu sahaja untuk Perlis, pengembara! Isi buku catatan sampai penuh, sawah ini jadi saksi.', 11),
(NULL, 203, 'e2_n3_s2', 'Hamparan sawah padi berkilau di bawah langit senja. Bendera Kedah berkibar di hujung tiang, jata negeri terpampang pada rumah besar, dan alat muzik di beranda mengalunkan lagu negeri.', 1),
(28, 203, 'e2_n3_s2', 'Pengembara! Sudah jauh berjalan ke Kedah? Duduk, duduk! Anda mencari ibu negeri Kedah, kan? Tahu jawapannya?', 2),
(NULL, 203, 'e2_n3_s2', 'Belum lagi, saya baru tiba! Tolong beritahu, saya sudah sedia mencatat.', 3),
(28, 203, 'e2_n3_s2', 'Ini jawapannya! Ibu negerinya Alor Setar, dan bandar dirajanya Anak Bukit.', 4),
(NULL, 203, 'e2_n3_s2', 'Eh, lagu apa pula itu? Radio itu seolah-olah mahu menyampuk!', 5),
(28, 203, 'e2_n3_s2', 'Lagu negerinya ialah ''Allah Selamatkan Sultan Mahkota''.', 6),
(NULL, 203, 'e2_n3_s2', 'Dua soalan lagi sebelum dakwat habis: siapakah ketua negeri ini, dan dari mana nama negerinya?', 7),
(28, 203, 'e2_n3_s2', 'Ketua negeri Kedah bergelar Sultan.', 8),
(28, 203, 'e2_n3_s2', 'Dan nama negeri ini pula? Perkataan ''Kheddah'', iaitu perangkap gajah.', 9),
(NULL, 203, 'e2_n3_s2', 'Habis catatan! Perjalanan ini bernilai setiap langkah.', 10),
(28, 203, 'e2_n3_s2', 'Sudah lengkap catatan Kedah, pengembara! Bawa bersama semangat sawah ini.', 11),
(NULL, 203, 'e2_n3_s3', 'Bau garam dan angin laut singgah di jeti yang sibuk. Bendera Pulau Pinang berkibar di jeti, jata negeri terpampang pada gerbang batu, dan gramofon di tepi laut mengalunkan lagu negeri.', 1),
(30, 203, 'e2_n3_s3', 'Pengembara! Cepat, bot sudah berbunyi! Anda mencari ibu negeri Pulau Pinang, kan? Sudah tahu jawapannya?', 2),
(NULL, 203, 'e2_n3_s3', 'Tidak tahu langsung! Sebab itulah saya datang. Mulakan, saya mencatat!', 3),
(30, 203, 'e2_n3_s3', 'Pena sudah sedia, bukan? Ibu negerinya Georgetown.', 4),
(NULL, 203, 'e2_n3_s3', 'Telinga saya tertarik pada radio itu. Lagu negeri apakah itu?', 5),
(30, 203, 'e2_n3_s3', 'Lagu negerinya ialah ''Untuk Negeri Kita''.', 6),
(NULL, 203, 'e2_n3_s3', 'Soalan terakhir, tetapi besar: gelaran ketua negerinya dan asal usul namanya?', 7),
(30, 203, 'e2_n3_s3', 'Ketua negeri Pulau Pinang bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 8),
(30, 203, 'e2_n3_s3', 'Dan nama negeri ini pula? Pokok pinang yang banyak tumbuh di pulau itu.', 9),
(NULL, 203, 'e2_n3_s3', 'Selesai! Saya akan baca catatan ini kepada setiap orang yang saya jumpa.', 10),
(30, 203, 'e2_n3_s3', 'Selesai catatan Pulau Pinang! Cepat naik bot, pengembara, kalau tidak anda tertinggal!', 11),
(NULL, 203, 'e2_n3_s4', 'Cahaya petang menyuluh halaman yang bersih disapu. Bendera Perak berkibar di tiang, jata negeri terpampang pada ukiran rumah, dan gramofon di atas meja mengalunkan lagu negeri.', 1),
(32, 203, 'e2_n3_s4', 'Pengembara! Cahaya petang pun seakan mahu mencatat sama. Anda mencari ibu negeri Perak, ya? Sudah tahu jawapannya?', 2),
(NULL, 203, 'e2_n3_s4', 'Belum! Tetapi pena sudah tajam dan buku catatan terbuka lebar. Ceritakanlah!', 3),
(32, 203, 'e2_n3_s4', 'Catatlah! Ibu negerinya Ipoh, dan bandar dirajanya Kuala Kangsar.', 4),
(NULL, 203, 'e2_n3_s4', 'Dan radio itu berbunyi sendiri! Lagu negeri apakah yang berkumandang itu?', 5),
(32, 203, 'e2_n3_s4', 'Lagu negerinya ialah ''Allah Lanjutkan Usia Sultan''.', 6),
(NULL, 203, 'e2_n3_s4', 'Satu lagi untuk buku catatan: siapakah ketua negerinya, dan dari mana nama negeri ini bermula?', 7),
(32, 203, 'e2_n3_s4', 'Ketua negeri Perak bergelar Sultan. Takhtanya berpindah secara bergilir mengikut sistem penggiliran yang unik.', 8),
(32, 203, 'e2_n3_s4', 'Dan nama negeri ini pula? Kilatan ikan atau bijih timah putih yang berkilat seperti perak.', 9),
(NULL, 203, 'e2_n3_s4', 'Sudah lengkap! Dakwat pun hampir kering, tetapi hati saya penuh.', 10),
(32, 203, 'e2_n3_s4', 'Catatan Perak sudah lengkap, pengembara! Nenek-nenek di sini ikut berbangga.', 11),
(NULL, 203, 'e2_n3_s5', 'Air sungai mengalir tenang dan burung berkicau di tebing. Bendera Selangor berkibar di tiang, jata negeri terpampang pada pintu gerbang rumah, dan gramofon di atas meja mengalunkan lagu negeri.', 1),
(30, 203, 'e2_n3_s5', 'Pengembara! Burung pun berhenti berkicau mahu dengar. Anda mencari ibu negeri Selangor, kan? Sudah tahu jawapannya?', 2),
(NULL, 203, 'e2_n3_s5', 'Belum lagi, saya baru tiba! Tolong beritahu, saya sudah sedia mencatat.', 3),
(30, 203, 'e2_n3_s5', 'Ini jawapannya! Ibu negerinya Shah Alam, dan bandar dirajanya Klang.', 4),
(NULL, 203, 'e2_n3_s5', 'Eh, lagu apa pula itu? Radio itu seolah-olah mahu menyampuk!', 5),
(30, 203, 'e2_n3_s5', 'Lagu negerinya ialah ''Duli Yang Maha Mulia''.', 6),
(NULL, 203, 'e2_n3_s5', 'Dua soalan lagi sebelum dakwat habis: siapakah ketua negeri ini, dan dari mana nama negerinya?', 7),
(30, 203, 'e2_n3_s5', 'Ketua negeri Selangor bergelar Sultan.', 8),
(30, 203, 'e2_n3_s5', 'Dan nama negeri ini pula? Sungai Selangor, pokok mentagau atau serangga selangur.', 9),
(NULL, 203, 'e2_n3_s5', 'Habis catatan! Perjalanan ini bernilai setiap langkah.', 10),
(30, 203, 'e2_n3_s5', 'Selesai Selangor! Pena anda pasti sudah penat, pengembara. Rehat di tebing sungai sebentar.', 11),
(NULL, 203, 'e2_n3_s6', 'Bumbung bergonjong rumah adat tegak di hujung halaman. Bendera Negeri Sembilan berkibar di tiang, jata negeri terpampang pada pintu pagar, dan gramofon di halaman mengalunkan lagu negeri.', 1),
(32, 203, 'e2_n3_s6', 'Pengembara! Naiklah ke halaman rumah adat ini. Anda mencari ibu negeri Negeri Sembilan, ya? Sudah tahu jawapannya?', 2),
(NULL, 203, 'e2_n3_s6', 'Tidak tahu langsung! Sebab itulah saya datang. Mulakan, saya mencatat!', 3),
(32, 203, 'e2_n3_s6', 'Pena sudah sedia, bukan? Ibu negerinya Seremban, dan bandar dirajanya Seri Menanti.', 4),
(NULL, 203, 'e2_n3_s6', 'Telinga saya tertarik pada radio itu. Lagu negeri apakah itu?', 5),
(32, 203, 'e2_n3_s6', 'Lagu negerinya ialah ''Berkatlah Yang di-Pertuan Besar''.', 6),
(NULL, 203, 'e2_n3_s6', 'Soalan terakhir, tetapi besar: gelaran ketua negerinya dan asal usul namanya?', 7),
(32, 203, 'e2_n3_s6', 'Ketua negeri Negeri Sembilan bergelar Yang di-Pertuan Besar. Beliau dipilih oleh Undang Yang Empat.', 8),
(32, 203, 'e2_n3_s6', 'Dan nama negeri ini pula? Penyatuan sembilan luak asal, dan ''nagari'' bermaksud wilayah.', 9),
(NULL, 203, 'e2_n3_s6', 'Selesai! Saya akan baca catatan ini kepada setiap orang yang saya jumpa.', 10),
(32, 203, 'e2_n3_s6', 'Beres untuk Negeri Sembilan, pengembara! Bumbung gonjong ini sudah menyaksikan semuanya.', 11),
(NULL, 203, 'e2_n3_s7', 'Bunyi sungai dan bayangan kubu lama menyambut pagi. Bendera Melaka berkibar di atas kubu, jata negeri terpampang pada papan kayu, dan gambus di atas tugu mengalunkan lagu negeri.', 1),
(30, 203, 'e2_n3_s7', 'Pengembara! Selamat datang ke bumi bersejarah. Anda mencari ibu negeri Melaka, kan? Sudah tahu jawapannya?', 2),
(NULL, 203, 'e2_n3_s7', 'Belum! Tetapi pena sudah tajam dan buku catatan terbuka lebar. Ceritakanlah!', 3),
(30, 203, 'e2_n3_s7', 'Catatlah! Ibu negerinya Bandar Melaka.', 4),
(NULL, 203, 'e2_n3_s7', 'Dan radio itu berbunyi sendiri! Lagu negeri apakah yang berkumandang itu?', 5),
(30, 203, 'e2_n3_s7', 'Lagu negerinya ialah ''Melaka Maju Jaya''.', 6),
(NULL, 203, 'e2_n3_s7', 'Satu lagi untuk buku catatan: siapakah ketua negerinya, dan dari mana nama negeri ini bermula?', 7),
(30, 203, 'e2_n3_s7', 'Ketua negeri Melaka bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 8),
(30, 203, 'e2_n3_s7', 'Dan nama negeri ini pula? Pokok Melaka tempat Parameswara berehat.', 9),
(NULL, 203, 'e2_n3_s7', 'Sudah lengkap! Dakwat pun hampir kering, tetapi hati saya penuh.', 10),
(30, 203, 'e2_n3_s7', 'Selesai Melaka! Sungai ini sudah menyimpan banyak catatan, kini giliran buku anda.', 11),
(NULL, 203, 'e2_n3_s8', 'Angin petang menyapu permukaan sungai yang berkilat. Bendera Johor berkibar di tepi sungai, jata negeri terpampang pada pintu gerbang, dan gramofon di kedai kopi mengalunkan lagu negeri.', 1),
(30, 203, 'e2_n3_s8', 'Pengembara! Duduk dahulu di tepi sungai. Anda mencari ibu negeri Johor, bukan? Sudah tahu jawapannya?', 2),
(NULL, 203, 'e2_n3_s8', 'Belum lagi, saya baru tiba! Tolong beritahu, saya sudah sedia mencatat.', 3),
(30, 203, 'e2_n3_s8', 'Ini jawapannya! Ibu negerinya Johor Bahru, dan bandar dirajanya Bandar Maharani.', 4),
(NULL, 203, 'e2_n3_s8', 'Eh, lagu apa pula itu? Radio itu seolah-olah mahu menyampuk!', 5),
(30, 203, 'e2_n3_s8', 'Lagu negerinya ialah ''Lagu Bangsa Johor''.', 6),
(NULL, 203, 'e2_n3_s8', 'Dua soalan lagi sebelum dakwat habis: siapakah ketua negeri ini, dan dari mana nama negerinya?', 7),
(30, 203, 'e2_n3_s8', 'Ketua negeri Johor bergelar Sultan.', 8),
(30, 203, 'e2_n3_s8', 'Dan nama negeri ini pula? Perkataan Arab ''Jauhar'', iaitu batu permata bernilai.', 9),
(NULL, 203, 'e2_n3_s8', 'Habis catatan! Perjalanan ini bernilai setiap langkah.', 10),
(30, 203, 'e2_n3_s8', 'Lengkap catatan Johor, pengembara! Berkilau seperti batu permata yang dikatakan itu.', 11),
(NULL, 203, 'e2_n3_s9', 'Kabus nipis naik dari sungai dan hutan di seberang. Bendera Pahang berkibar di tepi sungai, jata negeri terpampang pada rumah besar, dan radio di atas meja kayu mengalunkan lagu negeri.', 1),
(29, 203, 'e2_n3_s9', 'Pengembara! Kabus ini pandai menyembunyikan jalan. Anda mencari ibu negeri Pahang, kan? Sudah tahu jawapannya?', 2),
(NULL, 203, 'e2_n3_s9', 'Tidak tahu langsung! Sebab itulah saya datang. Mulakan, saya mencatat!', 3),
(29, 203, 'e2_n3_s9', 'Pena sudah sedia, bukan? Ibu negerinya Kuantan, dan bandar dirajanya Pekan.', 4),
(NULL, 203, 'e2_n3_s9', 'Telinga saya tertarik pada radio itu. Lagu negeri apakah itu?', 5),
(29, 203, 'e2_n3_s9', 'Lagu negerinya ialah ''Allah Selamatkan Sultan Kami''.', 6),
(NULL, 203, 'e2_n3_s9', 'Soalan terakhir, tetapi besar: gelaran ketua negerinya dan asal usul namanya?', 7),
(29, 203, 'e2_n3_s9', 'Ketua negeri Pahang bergelar Sultan.', 8),
(29, 203, 'e2_n3_s9', 'Dan nama negeri ini pula? Pokok mahang, juga dikenali sebagai Inderapura.', 9),
(NULL, 203, 'e2_n3_s9', 'Selesai! Saya akan baca catatan ini kepada setiap orang yang saya jumpa.', 10),
(29, 203, 'e2_n3_s9', 'Selesai Pahang! Buku catatan anda kini lebih berat daripada beg galas, bukan?', 11),
(NULL, 203, 'e2_n3_s10', 'Ombak berbuih memukul pantai dan layang-layang camar berputar. Bendera Terengganu berkibar di tepi pantai, jata negeri terpampang pada dinding rumah, dan alat muzik di beranda mengalunkan lagu negeri.', 1),
(27, 203, 'e2_n3_s10', 'Pengembara! Ombak pun macam mahu mengintai buku catatan anda. Anda mencari ibu negeri Terengganu, ya? Sudah tahu jawapannya?', 2),
(NULL, 203, 'e2_n3_s10', 'Belum! Tetapi pena sudah tajam dan buku catatan terbuka lebar. Ceritakanlah!', 3),
(27, 203, 'e2_n3_s10', 'Catatlah! Ibu negerinya Kuala Terengganu.', 4),
(NULL, 203, 'e2_n3_s10', 'Dan radio itu berbunyi sendiri! Lagu negeri apakah yang berkumandang itu?', 5),
(27, 203, 'e2_n3_s10', 'Lagu negerinya ialah ''Selamat Sultan''.', 6),
(NULL, 203, 'e2_n3_s10', 'Satu lagi untuk buku catatan: siapakah ketua negerinya, dan dari mana nama negeri ini bermula?', 7),
(27, 203, 'e2_n3_s10', 'Ketua negeri Terengganu bergelar Sultan.', 8),
(27, 203, 'e2_n3_s10', 'Dan nama negeri ini pula? ''Taring anu'' (taring binatang liar) atau ''terang ganu'' (pelangi).', 9),
(NULL, 203, 'e2_n3_s10', 'Sudah lengkap! Dakwat pun hampir kering, tetapi hati saya penuh.', 10),
(27, 203, 'e2_n3_s10', 'Lengkap Terengganu! Biar ombak yang memadam jejak kaki, tapi catatan anda kekal.', 11),
(NULL, 203, 'e2_n3_s11', 'Ukiran kayu berkilat di rumah tua yang harum dengan bunga. Bendera Kelantan berkibar di tiang, jata negeri terpampang pada gerbang rumah, dan rebana dan serunai di atas meja mengalunkan lagu negeri.', 1),
(32, 203, 'e2_n3_s11', 'Pengembara! Rumah ukiran ini sudah lama menanti tetamu. Anda mencari ibu negeri Kelantan, kan? Sudah tahu jawapannya?', 2),
(NULL, 203, 'e2_n3_s11', 'Belum lagi, saya baru tiba! Tolong beritahu, saya sudah sedia mencatat.', 3),
(32, 203, 'e2_n3_s11', 'Ini jawapannya! Ibu negerinya Kota Bharu.', 4),
(NULL, 203, 'e2_n3_s11', 'Eh, lagu apa pula itu? Radio itu seolah-olah mahu menyampuk!', 5),
(32, 203, 'e2_n3_s11', 'Lagu negerinya ialah ''Selamat Sultan''.', 6),
(NULL, 203, 'e2_n3_s11', 'Dua soalan lagi sebelum dakwat habis: siapakah ketua negeri ini, dan dari mana nama negerinya?', 7),
(32, 203, 'e2_n3_s11', 'Ketua negeri Kelantan bergelar Sultan.', 8),
(32, 203, 'e2_n3_s11', 'Dan nama negeri ini pula? Kilatan cahaya terang atau pokok gelam hutan.', 9),
(NULL, 203, 'e2_n3_s11', 'Habis catatan! Perjalanan ini bernilai setiap langkah.', 10),
(32, 203, 'e2_n3_s11', 'Selesai Kelantan, pengembara! Ukiran kayu ini pun macam tersenyum melihat catatan anda.', 11),
(NULL, 203, 'e2_n3_s12', 'Angin teluk berhembus sambil gong kecil berdenting jauh. Bendera Sabah berkibar di tiang, jata negeri terpampang pada bangunan batu, dan alat muzik di pondok mengalunkan lagu negeri.', 1),
(33, 203, 'e2_n3_s12', 'Pengembara! Angin teluk bawa khabar Anda tiba. Anda mencari ibu negeri Sabah, kan? Sudah tahu jawapannya?', 2),
(NULL, 203, 'e2_n3_s12', 'Tidak tahu langsung! Sebab itulah saya datang. Mulakan, saya mencatat!', 3),
(33, 203, 'e2_n3_s12', 'Pena sudah sedia, bukan? Ibu negerinya Kota Kinabalu.', 4),
(NULL, 203, 'e2_n3_s12', 'Telinga saya tertarik pada radio itu. Lagu negeri apakah itu?', 5),
(33, 203, 'e2_n3_s12', 'Lagu negerinya ialah ''Sabah Tanah Airku''.', 6),
(NULL, 203, 'e2_n3_s12', 'Soalan terakhir, tetapi besar: gelaran ketua negerinya dan asal usul namanya?', 7),
(33, 203, 'e2_n3_s12', 'Ketua negeri Sabah bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 8),
(33, 203, 'e2_n3_s12', 'Dan nama negeri ini pula? Sejenis pisang, iaitu pisang saba atau pisang jaba.', 9),
(NULL, 203, 'e2_n3_s12', 'Selesai! Saya akan baca catatan ini kepada setiap orang yang saya jumpa.', 10),
(33, 203, 'e2_n3_s12', 'Selesai Sabah! Gong kecil itu berdenting kerana gembira, pengembara.', 11),
(NULL, 203, 'e2_n3_s13', 'Air sungai berwarna teh mengalir lambat di bawah tebing. Bendera Sarawak berkibar tinggi, jata negeri terpampang pada pintu gerbang, dan alat muzik di atas tugu mengalunkan lagu negeri.', 1),
(34, 203, 'e2_n3_s13', 'Pengembara! Naik sampan, sampai sini jauh juga. Anda mencari ibu negeri Sarawak, kan? Sudah tahu jawapannya?', 2),
(NULL, 203, 'e2_n3_s13', 'Belum! Tetapi pena sudah tajam dan buku catatan terbuka lebar. Ceritakanlah!', 3),
(34, 203, 'e2_n3_s13', 'Catatlah! Ibu negerinya Kuching.', 4),
(NULL, 203, 'e2_n3_s13', 'Dan radio itu berbunyi sendiri! Lagu negeri apakah yang berkumandang itu?', 5),
(34, 203, 'e2_n3_s13', 'Lagu negerinya ialah ''Ibu Pertiwiku''.', 6),
(NULL, 203, 'e2_n3_s13', 'Satu lagi untuk buku catatan: siapakah ketua negerinya, dan dari mana nama negeri ini bermula?', 7),
(34, 203, 'e2_n3_s13', 'Ketua negeri Sarawak bergelar Yang di-Pertua Negeri, dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.', 8),
(34, 203, 'e2_n3_s13', 'Dan nama negeri ini pula? Sungai Sarawak, logam antimoni (cerava) atau ''serah kepada awak''.', 9),
(NULL, 203, 'e2_n3_s13', 'Sudah lengkap! Dakwat pun hampir kering, tetapi hati saya penuh.', 10),
(34, 203, 'e2_n3_s13', 'Selesai Sarawak, pengembara! Sungai ini sudah menyimpan banyak cerita, kini buku anda pula.', 11),
(NULL, 203, 'e2_n3_s14', 'Lampu bandar menyala dan bunyi trafik bersahut-sahutan. Bendera Wilayah Persekutuan berkibar di tiang, jata negeri terpampang pada gerbang batu, dan gramofon di atas tugu mengalunkan lagu negeri.', 1),
(38, 203, 'e2_n3_s14', 'Pengembara! Bunyi trafik pun macam sorak sambutan. Anda mencari lagu negeri Wilayah Persekutuan, kan? Sudah tahu jawapannya?', 2),
(NULL, 203, 'e2_n3_s14', 'Belum lagi, saya baru tiba! Tolong beritahu, saya sudah sedia mencatat.', 3),
(38, 203, 'e2_n3_s14', 'Mari mulakan dengan lagu. Lagu negerinya ialah ''Maju dan Sejahtera''.', 4),
(NULL, 203, 'e2_n3_s14', 'Dan ibu negerinya pula, adakah ada?', 5),
(38, 203, 'e2_n3_s14', 'Wilayah Persekutuan tidak mempunyai ibu negeri tersendiri; ketiga-tiganya ialah Kuala Lumpur, Labuan dan Putrajaya.', 6),
(NULL, 203, 'e2_n3_s14', 'Dua soalan lagi sebelum dakwat habis: siapakah ketua negeri ini, dan dari mana nama negerinya?', 7),
(38, 203, 'e2_n3_s14', 'Ketua negeri bagi tiga Wilayah Persekutuan ialah Yang di-Pertuan Agong.', 8),
(38, 203, 'e2_n3_s14', 'Dan nama negeri ini pula? Muara berlumpur (KL), labuhan (Labuan), sempena Tunku (Putrajaya).', 9),
(NULL, 203, 'e2_n3_s14', 'Habis catatan! Perjalanan ini bernilai setiap langkah.', 10),
(38, 203, 'e2_n3_s14', 'Selesai Wilayah Persekutuan! Buku catatan anda kini lengkap, tahniah pengembara!', 11);
INSERT INTO QuestionBank (bankID, eraID) VALUES (2, 2)
INSERT INTO Question (questionID, bankID, questionText, option_a, option_b, option_c, option_d, correctAnswer, hint, explanation) VALUES
(201, 2, 'Nama Pulau Pinang diambil sempena apa?', 'Pokok mahang yang banyak tumbuh di pulau itu', 'Sungai Pinang yang mengalir di tengah pulau itu', 'Buah pinang yang dijual pedagang Siam di pulau itu', 'Pokok pinang yang banyak tumbuh di pulau itu', 'D', 'Pulau itu dahulu dikenali sebagai Pulo Ka Satu atau Tanjong Penaga.', 'Pulau Pinang diambil sempena pokok pinang yang banyak tumbuh di pulau itu. Dahulu ia dikenali sebagai Pulo Ka Satu atau Tanjong Penaga.'),
(202, 2, 'Nama Pahang diambil daripada nama pokok apa?', 'Pokok mahang', 'Pokok pinang', 'Pokok mentagau', 'Pokok gelam hutan', 'A', 'Catatan lama juga menyebut Pahang sebagai Inderapura.', 'Nama Pahang diambil daripada pokok mahang. Pahang juga dikenali sebagai Inderapura dalam catatan lama.'),
(203, 2, 'Nama Johor berasal daripada perkataan Arab ''Jauhar''. Apakah maksudnya?', 'Perangkap untuk menangkap gajah', 'Tempat persinggahan kapal dagang', 'Kilatan cahaya yang terang', 'Batu permata yang bernilai', 'D', 'Dalam Sulalatus Salatin, Johor dikenali sebagai Ujung Tanah.', 'Johor berasal daripada perkataan Arab ''Jauhar'', iaitu batu permata bernilai. Dalam Sulalatus Salatin, Johor dikenali sebagai Ujung Tanah.'),
(204, 2, 'Menurut satu pendapat, nama Kedah berasal daripada perkataan ''Kheddah''. Apakah maksudnya?', 'Perangkap gajah', 'Kelapa hanyut', 'Batu permata bernilai', 'Taring harimau liar', 'A', 'Perkataan itu berkait dengan binatang besar yang ditangkap.', 'Menurut satu pendapat, Kedah berasal daripada ''Kheddah'', iaitu perangkap gajah. Pendapat lain menyebut perkataan Arab ''Qadah'' atau ''Kadaram'' dalam rujukan India.'),
(205, 2, 'Menurut satu pendapat, nama Perlis berasal daripada perkataan Siam ''phrau loi''. Apakah maksudnya?', 'Perangkap gajah', 'Kelapa hanyut', 'Pisang jaba', 'Taring harimau', 'B', 'Perlis juga dikaitkan dengan perkataan tempatan ''peroleh''.', 'Perlis dikatakan daripada perkataan Siam ''phrau loi'' (kelapa hanyut) atau perkataan tempatan ''peroleh''. Ia juga dikaitkan dengan tokoh tempatan Tok Perlis.'),
(206, 2, 'Salah satu pendapat mengaitkan nama Perak dengan apa?', 'Warna bijih timah putih yang berkilat seperti perak', 'Warna bijih timah hitam yang berkilat seperti arang', 'Warna pasir sungai yang berkilat seperti emas', 'Warna daun pokok yang berkilat seperti zamrud', 'A', 'Pendapat lain mengaitkannya dengan kilatan ikan di dalam air.', 'Nama Perak dikaitkan dengan kilatan ikan di dalam air atau warna bijih timah putih yang berkilat seperti perak.'),
(207, 2, 'Menurut satu pendapat, nama Selangor diambil sempena apa?', 'Sungai Klang', 'Sungai Selangor', 'Sungai Bernam', 'Sungai Langat', 'B', 'Pendapat lain menyebut pokok mentagau di kuala sungai.', 'Selangor dikaitkan dengan Sungai Selangor, pokok mentagau di kuala sungai, atau sejenis serangga bernama selangur.'),
(208, 2, 'Negeri Sembilan terbentuk daripada penyatuan berapa luak asal?', 'Tujuh luak', 'Lima luak', 'Dua belas luak', 'Sembilan luak', 'D', 'Antaranya Sungai Ujong, Jelebu, Rembau dan Johol.', 'Negeri Sembilan terbentuk daripada penyatuan sembilan luak asal, antaranya Sungai Ujong, Jelebu, Rembau dan Johol.'),
(209, 2, 'Perkataan ''negeri'' dalam Negeri Sembilan berasal daripada ''nagari''. Apakah maksudnya?', 'Wilayah', 'Istana', 'Kampung kecil', 'Sungai besar', 'A', 'Sembilan luak asal itu bersatu menjadi satu wilayah.', 'Perkataan negeri berasal daripada ''nagari'', iaitu wilayah.'),
(210, 2, 'Nama Melaka dikatakan sempena pokok Melaka tempat siapa berehat?', 'Hang Tuah', 'Tun Perak', 'Parameswara', 'Sultan Mahmud Shah', 'C', 'Beliau datang mencari tempat untuk membuka petempatan baharu.', 'Nama Melaka dikaitkan dengan pokok Melaka tempat Parameswara berehat. Rujukan Arab pula mengaitkannya dengan ''Malakat''.'),
(211, 2, 'Rujukan Arab mengaitkan nama Melaka dengan ''Malakat''. Apakah maksudnya?', 'Tempat berlabuh kapal perang', 'Pusat perhimpunan pedagang', 'Kota yang dikelilingi parit', 'Pelabuhan yang berlumpur', 'B', 'Melaka terkenal sebagai tempat pedagang berkumpul.', 'Rujukan Arab mengaitkan Melaka dengan ''Malakat'', iaitu pusat perhimpunan pedagang.'),
(212, 2, 'Dalam Sulalatus Salatin, negeri manakah dikenali sebagai Ujung Tanah?', 'Johor', 'Pahang', 'Kelantan', 'Terengganu', 'A', 'Namanya berasal daripada perkataan Arab yang bermaksud permata.', 'Dalam Sulalatus Salatin, Johor dikenali sebagai Ujung Tanah.'),
(213, 2, 'Dalam rujukan China, negeri manakah disebut Ho-lan-tan?', 'Pahang', 'Terengganu', 'Kedah', 'Kelantan', 'D', 'Namanya dikaitkan dengan kilatan atau pokok gelam hutan.', 'Rujukan China menyebut Kelantan sebagai Ho-lan-tan.'),
(214, 2, '''Terang ganu'' dalam satu pendapat asal usul nama Terengganu bermaksud apa?', 'Bulan penuh', 'Bintang timur', 'Pelangi', 'Cahaya fajar', 'C', 'Pendapat lain menyebut taring anu, iaitu taring binatang liar.', 'Terengganu dikaitkan dengan ''taring anu'' (taring harimau atau binatang liar) atau ''terang ganu'' (pelangi).'),
(215, 2, 'Antara asal usul nama Sarawak ialah logam antimoni. Apakah nama logam itu dalam cerita tempatan?', 'Cerava', 'Gelam', 'Saba', 'Mentagau', 'A', 'Sarawak juga dikaitkan dengan Sungai Sarawak.', 'Nama Sarawak dikaitkan dengan Sungai Sarawak, logam antimoni (cerava) atau dialog ''serah kepada awak''.'),
(216, 2, 'Nama Sabah diambil daripada sejenis apa?', 'Padi, iaitu padi saba', 'Pisang, iaitu pisang saba', 'Ubi, iaitu ubi jaba', 'Kelapa, iaitu kelapa saba', 'B', 'Pisang itu juga disebut pisang jaba.', 'Nama Sabah diambil daripada sejenis pisang iaitu pisang saba (pisang jaba).'),
(217, 2, 'Nama Kuala Lumpur berasal daripada kawasan apa?', 'Muara sungai yang berpasir akibat penerokaan hutan paya', 'Muara sungai yang berlumpur akibat perlombongan bijih timah', 'Muara sungai yang berbatu akibat pembinaan jambatan lama', 'Muara sungai yang berkarang akibat pembukaan pelabuhan', 'B', 'Lumpur itu datang daripada kegiatan melombong.', 'Kuala Lumpur berasal daripada kawasan muara sungai yang berlumpur akibat perlombongan bijih timah.'),
(218, 2, 'Nama Labuan berasal daripada perkataan ''labuhan''. Apakah maksudnya?', 'Tempat pelabuhan dan persinggahan kapal', 'Tempat penempatan dan perlindungan nelayan', 'Tempat perhimpunan dan perniagaan pedagang', 'Tempat penanaman dan pengeringan kelapa', 'A', 'Kapal-kapal singgah di sana.', 'Labuan berasal daripada ''labuhan'', iaitu tempat pelabuhan atau persinggahan kapal.'),
(219, 2, 'Nama Putrajaya diambil sempena nama siapa?', 'Tun Abdul Razak Hussein', 'Tun Hussein Onn', 'Tunku Abdul Rahman Putra Al-Haj', 'Tun Dr. Mahathir Mohamad', 'C', 'Beliau ialah Perdana Menteri Pertama.', 'Putrajaya diambil sempena nama Perdana Menteri Pertama, Tunku Abdul Rahman Putra Al-Haj, manakala jaya bermaksud kejayaan.'),
(220, 2, 'Apakah gelaran ketua negeri bagi Perlis?', 'Sultan', 'Yang di-Pertuan Besar', 'Raja', 'Yang di-Pertua Negeri', 'C', 'Hanya satu negeri menggunakan gelaran ini.', 'Ketua negeri Perlis bergelar Raja.'),
(221, 2, 'Siapakah yang memilih Yang di-Pertuan Besar Negeri Sembilan?', 'Dewan Negeri Sembilan', 'Undang Yang Empat', 'Majlis Raja-Raja', 'Yang di-Pertuan Agong', 'B', 'Pemilih itu ialah pembesar adat negeri ini.', 'Yang di-Pertuan Besar Negeri Sembilan dipilih oleh Undang Yang Empat.'),
(222, 2, 'Negeri manakah menggunakan sistem penggiliran takhta yang unik?', 'Perak', 'Kedah', 'Johor', 'Pahang', 'A', 'Bandar dirajanya Kuala Kangsar.', 'Perak menggunakan sistem penggiliran takhta yang unik.'),
(223, 2, 'Berapa tahun satu penggal jawatan Yang di-Pertua Negeri?', 'Empat tahun', 'Dua tahun', 'Tiga tahun', 'Lima tahun', 'A', 'Jawatan ini dilantik oleh Yang di-Pertuan Agong.', 'Yang di-Pertua Negeri dilantik oleh Yang di-Pertuan Agong untuk penggal empat tahun.'),
(224, 2, 'Siapakah yang melantik Yang di-Pertua Negeri?', 'Majlis Raja-Raja', 'Yang di-Pertuan Agong', 'Perdana Menteri', 'Ketua Menteri', 'B', 'Pelantik itu ialah ketua utama negara.', 'Yang di-Pertua Negeri dilantik oleh Yang di-Pertuan Agong.'),
(225, 2, 'Negeri manakah diketuai oleh Yang di-Pertua Negeri?', 'Kedah', 'Perlis', 'Pulau Pinang', 'Negeri Sembilan', 'C', 'Ada empat negeri semuanya, dua di Semenanjung dan dua di Borneo.', 'Yang di-Pertua Negeri mengetuai Melaka, Pulau Pinang, Sabah dan Sarawak.'),
(226, 2, 'Berapa buah negeri yang diketuai oleh Sultan?', 'Lima buah', 'Enam buah', 'Lapan buah', 'Tujuh buah', 'D', 'Perak, Kedah dan Selangor antaranya.', 'Tujuh negeri diketuai Sultan: Johor, Kedah, Kelantan, Pahang, Perak, Selangor dan Terengganu.'),
(227, 2, 'Siapakah ketua negeri bagi Kuala Lumpur, Labuan dan Putrajaya?', 'Yang di-Pertuan Agong', 'Perdana Menteri', 'Datuk Bandar', 'Yang di-Pertua Negeri', 'A', 'Beliau ialah Ketua Utama Negara.', 'Yang di-Pertuan Agong ialah Ketua Utama Negara dan ketua negeri bagi tiga Wilayah Persekutuan.'),
(228, 2, 'Pasangan negeri dan gelaran ketua negeri manakah yang betul?', 'Perlis dan Sultan', 'Sabah dan Raja', 'Melaka dan Yang di-Pertuan Besar', 'Negeri Sembilan dan Yang di-Pertuan Besar', 'D', 'Ketua negeri itu dipilih oleh Undang Yang Empat.', 'Negeri Sembilan diketuai Yang di-Pertuan Besar. Perlis diketuai Raja, Sabah dan Melaka diketuai Yang di-Pertua Negeri.'),
(229, 2, 'Negeri manakah diketuai oleh Sultan?', 'Melaka', 'Sabah', 'Selangor', 'Perlis', 'C', 'Bandar dirajanya ialah Klang.', 'Selangor diketuai Sultan. Melaka dan Sabah diketuai Yang di-Pertua Negeri, manakala Perlis diketuai Raja.'),
(230, 2, 'Apakah ibu negeri Perlis?', 'Arau', 'Kangar', 'Alor Setar', 'Kuala Kangsar', 'B', 'Bandar dirajanya ialah Arau.', 'Kangar ialah ibu negeri Perlis, manakala bandar dirajanya ialah Arau.'),
(231, 2, 'Apakah bandar diraja Perlis?', 'Kangar', 'Anak Bukit', 'Pekan', 'Arau', 'D', 'Ibu negerinya ialah Kangar.', 'Arau ialah bandar diraja Perlis.'),
(232, 2, 'Apakah bandar diraja Perak?', 'Ipoh', 'Kuala Kangsar', 'Klang', 'Seri Menanti', 'B', 'Ibu negerinya ialah Ipoh.', 'Kuala Kangsar ialah bandar diraja Perak, manakala ibu negerinya ialah Ipoh.'),
(233, 2, 'Apakah bandar diraja Kedah?', 'Alor Setar', 'Arau', 'Pekan', 'Anak Bukit', 'D', 'Ibu negerinya ialah Alor Setar.', 'Anak Bukit ialah bandar diraja Kedah, manakala ibu negerinya ialah Alor Setar.'),
(234, 2, 'Apakah bandar diraja Pahang?', 'Kuantan', 'Klang', 'Pekan', 'Arau', 'C', 'Ibu negerinya ialah Kuantan.', 'Pekan ialah bandar diraja Pahang, manakala ibu negerinya ialah Kuantan.'),
(235, 2, 'Apakah bandar diraja Negeri Sembilan?', 'Seremban', 'Seri Menanti', 'Pekan', 'Anak Bukit', 'B', 'Ibu negerinya ialah Seremban.', 'Seri Menanti ialah bandar diraja Negeri Sembilan, manakala ibu negerinya ialah Seremban.'),
(236, 2, 'Apakah bandar diraja Johor?', 'Johor Bahru', 'Klang', 'Bandar Maharani', 'Pekan', 'C', 'Ibu negerinya ialah Johor Bahru.', 'Bandar Maharani ialah bandar diraja Johor, manakala ibu negerinya ialah Johor Bahru.'),
(237, 2, 'Apakah bandar diraja Selangor?', 'Shah Alam', 'Seremban', 'Kuala Kangsar', 'Klang', 'D', 'Ibu negerinya ialah Shah Alam.', 'Klang ialah bandar diraja Selangor, manakala ibu negerinya ialah Shah Alam.'),
(238, 2, 'Apakah ibu negeri Selangor?', 'Shah Alam', 'Klang', 'Seremban', 'Kuala Kangsar', 'A', 'Bandar dirajanya ialah Klang.', 'Shah Alam ialah ibu negeri Selangor.'),
(239, 2, 'Apakah ibu negeri Pahang?', 'Pekan', 'Kota Bharu', 'Kuala Terengganu', 'Kuantan', 'D', 'Bandar dirajanya ialah Pekan.', 'Kuantan ialah ibu negeri Pahang.'),
(240, 2, 'Apakah ibu negeri Sabah?', 'Kuching', 'Kota Bharu', 'Kota Kinabalu', 'Kuala Terengganu', 'C', 'Ibu negeri itu terletak di Borneo.', 'Kota Kinabalu ialah ibu negeri Sabah.'),
(241, 2, 'Apakah ibu negeri Sarawak?', 'Kota Kinabalu', 'Kuching', 'Kota Bharu', 'Kuala Kangsar', 'B', 'Lagu negerinya ialah Ibu Pertiwiku.', 'Kuching ialah ibu negeri Sarawak.'),
(242, 2, 'Apakah ibu negeri Pulau Pinang?', 'Alor Setar', 'George Town', 'Ipoh', 'Bandar Melaka', 'B', 'Ibu negeri itu terletak di sebuah pulau.', 'George Town ialah ibu negeri Pulau Pinang.'),
(243, 2, 'Apakah lagu negeri Perak?', 'Allah Selamatkan Sultan Mahkota', 'Allah Selamatkan Sultan Kami', 'Berkatlah Yang di-Pertuan Besar', 'Allah Lanjutkan Usia Sultan', 'D', 'Tajuknya menyebut usia.', 'Lagu negeri Perak ialah Allah Lanjutkan Usia Sultan.'),
(244, 2, 'Apakah lagu negeri Kedah?', 'Allah Selamatkan Sultan Mahkota', 'Allah Lanjutkan Usia Sultan', 'Allah Selamatkan Sultan Kami', 'Duli Yang Maha Mulia', 'A', 'Tajuknya menyebut mahkota.', 'Lagu negeri Kedah ialah Allah Selamatkan Sultan Mahkota.'),
(245, 2, 'Apakah lagu negeri Negeri Sembilan?', 'Duli Yang Maha Mulia', 'Allah Lanjutkan Usia Sultan', 'Berkatlah Yang di-Pertuan Besar', 'Lagu Bangsa Johor', 'C', 'Tajuknya menyebut gelaran ketua negerinya.', 'Lagu negeri Negeri Sembilan ialah Berkatlah Yang di-Pertuan Besar.'),
(246, 2, 'Apakah lagu negeri Melaka?', 'Maju dan Sejahtera', 'Sabah Tanah Airku', 'Lagu Bangsa Johor', 'Melaka Maju Jaya', 'D', 'Tajuknya menyebut nama negeri itu sendiri.', 'Lagu negeri Melaka ialah Melaka Maju Jaya.'),
(247, 2, 'Apakah lagu negeri Sabah?', 'Sabah Tanah Airku', 'Ibu Pertiwiku', 'Melaka Maju Jaya', 'Maju dan Sejahtera', 'A', 'Tajuknya menyebut tanah air.', 'Lagu negeri Sabah ialah Sabah Tanah Airku.'),
(248, 2, 'Apakah lagu negeri Sarawak?', 'Sabah Tanah Airku', 'Selamat Sultan', 'Ibu Pertiwiku', 'Lagu Bangsa Johor', 'C', 'Tajuknya menyebut ibu pertiwi.', 'Lagu negeri Sarawak ialah Ibu Pertiwiku.'),
(249, 2, 'Apakah lagu negeri Johor?', 'Melaka Maju Jaya', 'Duli Yang Maha Mulia', 'Lagu Bangsa Johor', 'Selamat Sultan', 'C', 'Tajuknya menyebut bangsa Johor.', 'Lagu negeri Johor ialah Lagu Bangsa Johor.'),
(250, 2, 'Apakah lagu negeri Selangor?', 'Selamat Sultan', 'Duli Yang Maha Mulia', 'Allah Selamatkan Sultan Kami', 'Berkatlah Yang di-Pertuan Besar', 'B', 'Tajuknya ialah ungkapan hormat kepada raja.', 'Lagu negeri Selangor ialah Duli Yang Maha Mulia.');
