-- ====================================================================
-- SejarahWira  |  ERA 2: Negeri-Negeri di Malaysia (Identiti dan Warisan Negeri)  |  seed_era2.sql
-- 3 naratif (14 + 14 + 14 babak = 42 babak), setiap babak ada 1 quest, serta 50 soalan.
-- Versi 4: dialog, kad babak dan reaksi ditulis semula supaya lebih hidup dan bergaya permainan (fakta tidak berubah).
--
-- Pelajar MERASUK jasad satu peranan dalam setiap naratif:
--   Naratif 1 (Rahsia di Sebalik Nama)                  = Tok Penglipur Lara (NPC 21)
--   Naratif 2 (Payung Negeri: Takhta dan Tanggungjawab) = Sultan (NPC 22)
--   Naratif 3 (Jejak Ibu Negeri dan Lagu Kebanggaan)    = Pengembara Warisan (NPC 26)
-- Baris dialog tanpa penutur (npcID NULL) ialah baris "Pemain" / "kau" yang dituturkan watak peranan.
-- Baris naratif tanpa babak (sceneID NULL): 1 = tugas bersejarah, 2 = pembuka pengajaran,
--   3 = pengenalan peranan oleh Pendekar Bayang.
-- Setiap quest ada "aftermath" (Akibat jika salah), pilihan salah jenis 3/5 ada "consequence",
-- dan satu "Giliran Anda" (turns). Data sahaja (tiada jadual atau lajur baharu).
-- Lencana, artifak dan kemajuan era TIDAK disentuh.
--
-- Kandungan: asal usul nama 13 negeri + 3 Wilayah Persekutuan, gelaran ketua negeri, ibu negeri,
-- bandar diraja dan lagu negeri. Gambar setiap negeri memaparkan bendera, jata dan radio/alat muzik; baris pertama setiap
-- babak dan titik Cari Bukti merujuk objek itu. Fakta reka bentuk bendera dan jata tidak diuji kerana tiada dalam bahan asal.
--
-- Jalankan SELEPAS seed.sql:
--   mysql --default-character-set=utf8mb4 -u root -p <nama_db> < database/seed_era2.sql
-- Selamat dijalankan berulang kali (kandungan Era 2 lama dipadam dahulu). Era lain tidak disentuh.
--
-- NOTA GAMBAR: nama fail negeri_melaka'.png dalam folder background ada tanda petik yang tersilap.
-- Namakan semula kepada negeri_melaka.png supaya latar Babak 2 Naratif 1 muncul.
-- ====================================================================
SET NAMES utf8mb4;
START TRANSACTION;

-- 1. Buang kandungan Era 2 lama (babak, dialog, quest, sokongan dipadam sekali: ON DELETE CASCADE).
DELETE FROM Narrative WHERE eraID = 2;

-- 2. NPC baharu Era 2 (nama fail gambar mengikut folder npc sebenar).
ON DUPLICATE KEY UPDATE name = VALUES(name), biography = VALUES(biography), contribution = VALUES(contribution), asset = VALUES(asset);

-- 3. Naratif

-- 4. Babak (sceneStoryline = kad garis masa dalam suara "kau"; asset = latar belakang)

-- 5. Quest (2 Cari Bukti, 3 Bantu Tokoh, 4 Padanan, 5 Nyahkod Clue)
--    instruction = taklimat misi, description = objektif pembelajaran

-- 6. Sokongan: baris babak = petunjuk babak; baris quest = bisikan (hint), catatan diari (explanation), pujian (feedback)

-- 7. Dialog: baris peranan (tanpa babak) dan dialog babak

-- 8. Bank soalan Era 2 (50 soalan aneka pilihan, ID 201-250)
ON DUPLICATE KEY UPDATE eraID = VALUES(eraID);

DELETE FROM Question WHERE bankID = 2;


COMMIT;